INSERT INTO `articles` VALUES (2332,1,'CONVOCAZIONE ASSEMBLEA ELETTIVA','<div class=\"newstext\">È convocata per il giorno giovedí 4 settembre 2025, in prima convocazione alle ore 01:00 ed occorrendo in seconda convocazione alle ore 21:00, presso i locali della Circoscrizione 5 in largo Petrarca, l\'assemblea dei soci dell\'A.D. Circolo Scacchistico “La Torre” col seguente ordine del giorno:\n							<ol>\n                            <li>Elezione organi statutari (Presidente e Consiglio Direttivo)\n							</li><li>Varie ed eventuali\n                            </li></ol>\n                            </div>','convocazione-assemblea-elettiva-2332','2025-08-20 00:00:00',NULL),(2333,1,'Torneo Summer – 20 luglio 2025','<div class=\"newstext\">\n								<p>Ottantuno partecipanti si sono dati battaglia al torneo Summer, svoltosi a Marina di Pisa domenica 20 luglio presso lo stabilimento balneare Blu Beach Club – Pappafico. Al termine dei sette turni di gioco, con tempo di riflessione 12\'+3\", è risultato vincitore il <b>MI Ilia Martinovici</b> con 6,5 punti su 7. Secondo classificato il <b>MF Doriano Tocchioni</b> (6/7), terzo classificato il polacco <b>Szymon Druzd</b> (6/7). Vanno a premio anche il <b>MI Pierluigi Piscopo</b> (quarto classificato con 5,5/7), <b>Andrea Davini</b> (quinto con 5,5/7), <b>Daniele Bettazzi</b> (sesto con 5,5/7). Migliori classificati per le fasce Elo under 1800 e under 1600, rispettivamente, <b>Cosimo Martini</b> (7º con 5,5/7) e <b>Michel Kocian</b> (26º con 4/7). Premio miglior giocatrice classificata a <b>Vittoria Spada</b> (21ª con 4,5/7).</p>\n							</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/tournament/F4riibzl\" target=\"_blank\">Risultati e classifica</a></div>','torneo-summer-20-luglio-2025-2333','2025-07-28 00:00:00',NULL),(2334,1,'Campionati Italiani Giovanili 2025','<div class=\"collegamentograndecentrato\"><img src=\"/foto/2025-06_CIG-Terrasini/2025-06_CIG-Terrasini-gruppo.jpg\" width=\"100%\"></div><div class=\"newstext\">Termina il CIG a Terrasini con i nostri 4 alfieri che hanno fatto un grande risultato. Leandro nella categoria under 16 termina con un ottimo 17esimo posto su 183 e 6,5/9 punti, raggiungendo la categoria 1N. Complimenti! Samuele nella categoria under 12 chiude 50esimo su 229 con un ottimo 5,5/9 punti. Giorgi nella categoria under 10 termina 18esimo su 172 con ben 6/9 punti e Manuel nella categoria under 8 termina 44esimo su 70 con 4/9. Siamo orgogliosi di voi!</div>','campionati-italiani-giovanili-2025-2334','2025-07-05 00:00:00',NULL),(2335,1,'Torneo Summer – 20 luglio 2025','<div class=\"collegamentograndecentrato\"><a href=\"/bandi/2025-07-20_torneo-Summer.jpeg\" target=\"_blank\"><img src=\"/bandi/2025-07-20_torneo-Summer.jpeg\" width=\"100%\"></a></div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/tournament/F4riibzl\" target=\"_blank\">Preiscrizioni</a></div>','torneo-summer-20-luglio-2025-2335','2025-07-03 00:00:00',NULL),(2336,1,'Torneo Repubblica – 31 maggio–2 giugno 2025','<div class=\"collegamentograndecentrato\"><a href=\"/foto/2025-05_Repubblica/sala.jpeg\" target=\"_blank\"><img src=\"/foto/2025-05_Repubblica/sala.jpeg\" width=\"100%\"></a></div><div class=\"newstext\">\n								<p>Il Circolo Scacchistico La Torre ringrazia tutti i 130 partecipanti che sono arrivati da tutta Italia e dall\'estero, che hanno contribuito a rendere il primo torneo della Repubblica una grande festa per gli scacchi. Un sentito ringraziamento va all\'assessore allo sport Frida Scarpa, che ci ha supportati e dato visibilità mediatica. Un prezioso ringraziamento al circolo Valdera che ci ha prestato parte del materiale scacchistico, perché con questi numeri non avremmo saputo come fare. Un enorme ringraziamento ai circoli di Livorno e Sarzana, per la loro partecipazione numerosa. Grazie anche a tutti i soci che hanno aiutato in questi 3 giorni di festa e al Circolo Matteotti “La Pagoda” che ci ha accolti come se fossimo a casa nostra, mettendo a nostra disposizione disposizione sale, giochi, giardino. Infine, un grazie agli sponsor perché, senza il loro sostegno, tutto questo non poteva essere realizzato. Davvero un momento di festa per gli scacchi. Grazie di cuore.</p>\n								<p><b>Torneo A</b> (Elo ≥ 1700; 24 partecipanti):<br>\n								1º classificato <b>Ilia Martinovici</b> (5/5)<br>\n								2º classificato <b>Doriano Tocchioni</b> (4/5)<br>\n								3º classificato <b>Alberto Fakhri Brunetti</b> (3,5/5)</p>\n\n								<p><b>Torneo B</b> (1500 ≤ Elo \n								1º classificato <b>Franciszek Gozdzikowski</b> (4,5/5)<br>\n								2º classificato <b>Michele Penza</b> (4/5)<br>\n								3º classificato <b>Ferruccio Lari</b> (4/5)</p>\n\n								<p><b>Torneo C</b> (Elo \n								1º classificato <b>Giorgi Lomtadze</b> (5/5)<br>\n								2ª classificata <b>Martina Salandin</b> (4,5/5)<br>\n								3º classificato <b>Davide Romele</b> (4,5/5)</p>\n							</div><div class=\"collegamentograndecentrato\">Risultati e classifiche <a href=\"https://vesus.org/tournament/pwO23f4k\" target=\"_blank\">Torneo A</a>, <a href=\"https://vesus.org/tournament/7Vtl_T3W\" target=\"_blank\">Torneo B</a>, <a href=\"https://vesus.org/tournament/7fLp_C0a\" target=\"_blank\">Torneo C</a></div>','torneo-repubblica-31-maggio-2-giugno-2025-2336','2025-07-03 00:00:00',NULL),(2337,1,'Il Circolo promuove due squadre in serie C al CIS 2025','<div class=\"newstext\">\n								Si è concluso il Campionato Italiano a Squadre (Campi Bisenzio (FI), 2–4 maggio 2025) al quale abbiamo preso parte con tre squadre nel girone Promozione.\n							</div><div class=\"newstext\">\n								<p>La squadra <b>\"Pisa La Torre\"</b> si presentava con l\'obiettivo dichiarato di conquistare la promozione in serie C. Schiva le insidie e conferma le attese, classificandosi al 2º posto su 30 squadre (8 punti: 4 vittorie-0 pareggi-1 sconfitta) e ottenendo la promozione che non ci riuscì l\'anno scorso. Sono scesi in campo Carlo Benvenuti (1,5/2), Lucio Calcagnile (3/3), Adriano Cappagli (0,5/2), Marco Montesanti (1/2), Simone Ramo (1,5/3), Leandro Trincherini (2,5/3) e Marco Cellucci (4/4 + 1 vittoria a forfait senza avversario).</p>\n								<p><b>\"Pisa L\'Alfiere\"</b> ottiene un inaspettato 10º posto (5 punti: 2-1-2) e conquista per il Circolo una seconda, insperata, promozione! Squadra non costruita per puntare alla promozione, ha ottenuto due belle vittorie in partenza di torneo ed è riuscita a contenere i danni quando gli incontri si sono fatti più impegnativi. Hanno giocato Cosimo Martini (2,5/3), Ruben La Delfa (2,5/3), Vincenzo Silluzio (1,5/5), Francesco Piqué (3/5) e Simone Mazzini (1,5/4).</p>\n								<p><b>\"Pisa Il Cavallo\"</b> inizia con una vittoria e poi accusa il colpo quando il livello sale, ottenendo comunque due buoni pareggi al quarto e al quinto turno. Chiude con un onorevole 22º posto (4 punti: 1-2-2). Hanno giocato Stefano Scigliano (1/3), Antonio Cerina (2/5), Samuele Soriani (0,5/5), Fabrizio Cecconi (2/4) e Marco Pallini (1/3).</p>\n								<p>Da sottolineare l\'ottima prestazione dei giovani Leandro e Marco in prima squadra, il ritorno alla scacchiera di Carlo Benvenuti dopo tanti anni, l\'esordio assoluto a tempo lungo di Simone Ramo e Ruben La Delfa.</p>\n								<p>Grazie a tutti!</p>\n							</div><div class=\"collegamentograndecentrato\"><a href=\"https://www.vegaresult.com/orion-trn/www5588/rankteam5.php\" target=\"_blank\">Risultati e classifiche</a></div>','il-circolo-promuove-due-squadre-in-serie-c-al-cis-2025-2337','2025-05-06 00:00:00',NULL),(2338,1,'Chessmaster','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">\n								Una serie di lezioni settimanali su un tema specifico, ognuna tenuta da un diverso istruttore di scacchi ogni venerdì sera!<br>\n								Calendario:<br>\n								<ul>\n								<li> 11 aprile: Pierluigi Piscopo (IM), \"La difesa siciliana\"</li>\n								<li> 18 aprile: Lorenzo Borrelli (Istruttore FSI), \"Come vincere una partita vinta\"</li>\n								<li> 2 maggio: Carlo Benvenuti (CM), \"Finali da posizione di svantaggio\"</li>\n								<li> 9 maggio: Genci Garunja, \"La difesa francese\"</li>\n								<li> 16 maggio: Lucio Calcagnile (CM), \"Lo Zugzwang, un\'arma anche nel mediogioco \"</li>\n								<li> 23 maggio: Ilia Martinovici (IM), \"Impariamo i finali di torre\"</li>\n								</ul>\n	\n							</div><div class=\"collegamentograndecentrato\"><a href=\"/corsi/chessmaster25.jpeg\" target=\"_blank\">Locandina</a></div>','chessmaster-2338','2025-03-20 00:00:00',NULL),(2339,1,'Corsi Coop Navacchio','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">\n								Partono due nuovi corsi di scacchi a cura del Circolo La Torre in collaborazione con UniCoop Firenze.\n								Tutti i corsi si svolgeranno il mercoledi sera dalle 20:30 alle 22:00 presso la piazzetta interna del centro commerciale di Navacchio (via del Fosso Vecchio).<br>\n								Calendario:<br>\n								<ul>\n								<li>Corso \"Introduzione al gioco degli scacchi\": 2,9,16,23,39 aprile. Costo 50 euro. Livello adulto principiante, nessuna conoscenza richiesta.</li>\n								<li>Corso \"Introduzione ai tatticismi e alle strategie di gioco\": 7,14,21,28 maggio, 4,11,18,25 giugno. Costo 70 euro. Richiesta conoscenza di base del gioco degli scacchi.</li>\n								</ul>\n								Parte del ricavato sarà devoluto alla fondazione \"Il Cuore si Scioglie\".<br>\n							</div><div class=\"collegamentograndecentrato\"><a href=\"/corsi/navacchio25.jpeg\" target=\"_blank\">Locandina</a></div>','corsi-coop-navacchio-2339','2025-03-20 00:00:00',NULL),(2340,1,'Convocazione assemblea ordinaria','<div class=\"newstext\">In Pisa, largo Petrarca 3, presso i locali della Circoscrizione 5, è convocata l\'assemblea annuale dei soci dell\'A.D. Circolo Scacchistico \"La Torre\", per il giorno giovedì 27 marzo 2025, alle ore 19:00 in prima convocazione ed occorrendo in seconda convocazione per lo stesso giorno alle ore 21:30, per discutere e deliberare sul seguente ordine del giorno:\n							<ol>\n								<li>Approvazione del bilancio chiuso al 31.12.2024, \n								Delibere inerenti e conseguenti;\n								</li><li>Discussione sull\'attività svolta nel 2024 e proposte per l\'attività 2025;\n								</li><li>Varie ed eventuali.\n								</li></ol>\n								Circolo Scacchistico La Torre \n							</div>','convocazione-assemblea-ordinaria-2340','2025-03-11 00:00:00',NULL),(2341,1,'Edicola della Legalità','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Ogni mercoledì fino al 22 aprile 2025 dalle ore 15:00 alle ore 17:00 si tiene il laboratorio di scacchi \"Fa la mossa giusta!\" in collaborazione con l\'Edicola della Legalità in piazza Martiri della Libertà a Pisa.\n							Un incontro aperto a tutti, dai principianti ai giocatori esperti, per giocare e imparare insieme. Ingresso  libero!\n							</div><div class=\"collegamentograndecentrato\"><a href=\"/corsi/edicola2025.jpeg\" target=\"_blank\">Locandina</a></div>','edicola-della-legalita-2341','2025-02-27 00:00:00',NULL),(2342,1,'Campionato Provinciale 2025','<div class=\"newstext\">Si è svolto a Pisa, presso la Domus Mazziniana, il Campionato Provinciale di Pisa 2025 a cui si è affiancato un torneo riservato ai giocatori con Elo inferiore a 1600. Ecco i risultati: </div><div class=\"newstext\">Campionato Provinciale: 1º CM Daniele <b>Cantoro</b> (5/5), 2º Romualdo <b>Vitale</b> (3,5/5), 3º Sara Duse Elena <b>Celati</b> (3,5/5).</div><div class=\"newstext\">Si aggiudica il titolo di Campione Provinciale e il premio miglior Elo Cellucci (3,5/5).</div><div class=\"newstext\">Miglior Elo Franchi (3/5).</div><div class=\"newstext\">Torneo Collaterale Elo Somma (4,5/5), 2º Giorgi <b>Lomtadze</b> (4/5), 3º Cosimo <b>Martini</b> (4/5).</div><div class=\"newstext\">Miglior under 18 Gioele <b>Pennoni</b> (4/5).</div><div class=\"newstext\">Miglior under 16 Mattia <b>Fella</b> (2,5/5).</div><div class=\"newstext\">Miglior under 10 Tommaso <b>Loberti</b> (3/5).</div><div class=\"newstext\">Miglior over 60 CM Lorenzo <b>Tamburini</b> (3/5).</div><div class=\"newstext\">Ringraziamo tutti i partecipanti, e la Domus Mazziniana per averci ospitato. Alla prossima!</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/JXYVa7bB\" target=\"_blank\">Risultati e classifiche</a></div>','campionato-provinciale-2025-2342','2025-02-14 00:00:00',NULL),(2343,1,'CAMPIONATO PROVINCIALE DI PISA 2025','<div class=\"newstext\">Sabato 1 e domenica 2 febbraio si svolgerà a Pisa presso la Domus Mazziniana in via M. D\'Azeglio 14 il Campionato Provinciale di Pisa 2025. Il torneo, omologato FSI/FIDE, valido per variazioni Elo FIDE standard, prevederà 5 turni a partire dalle 14:00 di sabato, con 60 minuti per giocatore e 30 secondi per mossa come cadenza di gioco. È previsto anche un torneo collaterale per giocatori con Elo inferiore a 1600.</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/JXYVa7bB\" target=\"_blank\">Preiscrizioni</a></div><div class=\"collegamentograndecentrato\"><a href=\"bandi/ProvPisa2025_v3.pdf\" target=\"_blank\">Bando</a></div><div class=\"collegamentograndecentrato\">\n								<img src=\"/pics/prov2025_v2.jpg\" width=\"100%\" border=\"1\">\n							</div>','campionato-provinciale-di-pisa-2025-2343','2025-01-12 00:00:00',NULL),(2344,1,'Scacchi in riva all\'Arno da giugno a settembre','<div class=\"newstext\">A partire da giugno e per tutta la stagione estiva il Circolo Scacchistico La Torre si unirà agli <a href=\"http://www.scacchinsorgenti.com/\" target=\"_blank\">Scacchi Insorgenti</a> per le serate di gioco <a href=\"http://arginiemargini.com/beach-chess/\" target=\"_blank\">Beach Chess</a>, ogni mercoledì sera presso Argini e Margini, il locale in riva all\'Arno accessibile dal lungarno Galilei nei pressi del ponte della Fortezza. La serata del mercoledì si aggiunge a quella del lunedì presso il Café Albatross.</div>','scacchi-in-riva-allarno-da-giugno-a-settembre-2344','2017-06-07 00:00:00',NULL),(2345,1,'I maratona blitz \"Schianta la torre\"','<div class=\"newstext\">Si è svolta a Pisa il 4 giugno 2017 la <b>I maratona blitz \"Schianta la torre\"</b>. Undici giocatori si sono affrontati in un doppio girone all\'italiana andata e ritorno. Vince Davide Rastelli davanti a Daniele Bettazzi e Francesco Lanotte.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/i-maratona-blitz-quotschianta-la-torrequot/\" target=\"_blank\">Risultati e classifica finale</a></div>','i-maratona-blitz-schianta-la-torre-2345','2017-06-07 00:00:00',NULL),(2346,1,'Riprendono gli incontri del circolo!','<div class=\"newstext\">A partire dal 30 gennaio, il Circolo si ritroverà ogni lunedí sera dalle 21:30 presso il <a href=\"https://www.facebook.com/cafealbatross/\">Café Albatross</a> (via Cavalca 64, Pisa) per le nostre serate scacchi di gioco libero e miglioramento a cui gli appassionati di tutti i livelli sono benvenuti. Non ci sono requisiti per partecipare, quindi accorrete numerosi!</div>','riprendono-gli-incontri-del-circolo-2346','2017-01-08 00:00:00',NULL),(2347,1,'Campionato interprovinciale di Pisa e Livorno 2017','<div class=\"newstext\">Si è svolto a Pisa i giorni 3, 4, 5 febbraio 2017, presso la Sala Convegni della Stazione Leopolda, il <b>Campionato interprovinciale di Pisa e Livorno</b>, valido come ottavi di finale del Campionato Italiano Assoluto per le due province. All\'open integrale, valido come campionato provinciale, si è affiancato un torneo under 1500. Vince il torneo open Federico Esposti con 4,5 punti su 5. Vengono eletti campioni provinciali Marco Messina per Pisa (2º assoluto) e Massimo Bardi per Livorno (3º assoluto). Stefano Patisso vince il torneo under 1500 con 4,5 punti su 5.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/festivals/campionato-interprovinciale-di-pisa-e-livorno-2017-e-torneo-under-1500/\" target=\"_blank\">Risultati e classifiche finali</a></div>','campionato-interprovinciale-di-pisa-e-livorno-2017-2347','2017-02-06 00:00:00',NULL),(2348,1,'Stagione estiva 2016','<div class=\"newstext\">Anche quest\'anno per la stagione estiva il Circolo si sposta presso <a href=\"http://arginiemargini.com/\" target=\"_blank\">Argini e Margini</a>, la spiaggetta situata sotto il Lungarno Galilei, vicino al Ponte della Fortezza. Saremo ospiti, come al solito, dell\'iniziativa <a href=\"http://arginiemargini.com/beach-chess/\" target=\"_blank\">Beach Chess</a>, organizzata dal gruppo <a href=\"http://www.scacchinsorgenti.com/\" target=\"_blank\">Scacchi Insorgenti</a>. L\'appuntamento è ogni mercoledì sera, a partire dall\'8 giugno, dalle 21:30. Ovviamente chiunque sia interessato è il benvenuto!</div>','stagione-estiva-2016-2348','2016-06-08 00:00:00',NULL),(2349,1,'Federico Esposti vince il Campionato Regionale Toscano 2016','<div class=\"newstext\">Si è svolto a Pisa i giorni 23, 24, 25 aprile 2016 presso la Sala Convegni della Stazione Leopolda il Campionato Regionale Toscano, quarti di finale del Campionato Italiano Assoluto, organizzato dal nostro circolo. Il torneo è stato vinto con 5,5 punti su 6 dal 1N lucchese Federico Esposti, che è anche il nuovo campione regionale e acquisisce il titolo di Candidato Maestro FSI. Secondo il CM Antonio Pinto con 5 punti; terzo con 4,5 punti il 1N Fabio Bartoli. Si qualificano alla semifinale CIA di luglio Antonio Pinto, Lucio Calcagnile e Romualdo Vitale.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/open-integrale-campionato-regionale-toscano-2016/\" target=\"_blank\">Risultati e classifica finale</a></div>','federico-esposti-vince-il-campionato-regionale-toscano-2016-2349','2016-05-23 00:00:00',NULL),(2350,1,'Campionato Provinciale di Pisa 2016','<div class=\"newstext\">Si è svolto i giorni 29, 30, 31 gennaio 2016 presso la Sala Convegni della Stazione Leopolda il Campionato Provinciale di Pisa, organizzato dal nostro circolo. Vince il torneo e il titolo di campione provinciale il nostro CM Lucio Calcagnile, con 4,5 punti su 5 partite. Secondo per spareggio Buchholz, ma a pari punti col vincitore, si classifica Massimiliano Boschi, mentre terzo con 4 punti è Matteo Brizzi. Vincono il premio delle due fasce Elo &lt; 1700 e &lt; 1500 rispettivamente Matteo Montorsi, con 3 punti, e Ludovico Battista, sempre con 3 punti e al suo esordio assoluto in una competizione agonistica. Si qualificano ai quarti di finale (campionato regionale) del Campionato Italiano Assoluto 2016 i giocatori Vitale, Cappagli, Di Liberti.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/campionato-provinciale-di-pisa-2016/standing/\" target=\"_blank\">Risultati e classifica finale</a></div>','campionato-provinciale-di-pisa-2016-2350','2016-01-31 00:00:00',NULL),(2351,1,'Grigory Seletsky vince la nona edizione del Semilampo di Pisa!','<div class=\"newstext\">Domenica 14 dicembre, presso l\'Hotel Repubblica Marinara, via Matteucci, 81, si è svolto il nono appuntamento col tradizionale Semilampo di Pisa. Ha vinto il Maestro FIDE ucraino Grigory Seletsky, con 7 punti su 9; secondo il MI Duilio Collutiis con 7,5; terzo Francesco Frugoli con 7. Vincitori di fascia Salvatore Federico (1750-1999), Andrea Targetti (1500-1749) e Davide Nocera (&lt;1500).</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/SemilampoPisa2014/\">Risultati e classifica finale</a></div>','grigory-seletsky-vince-la-nona-edizione-del-semilampo-di-pisa-2351','2014-12-15 00:00:00',NULL),(2352,1,'Torneo promozionale alla Stazione Leopolda','<div class=\"newstext\">Dieci giocatori hanno preso parte al torneo promozionale organizzato dal nostro circolo in occasione del <b>1º festival pisano dei giochi della mente</b>, svoltosi domenica 22 giugno presso la Stazione Leopolda. Fra i partecipanti, ben sette erano alla loro prima esperienza in un torneo, e proprio questo dato ci dà grande soddisfazione e segna il successo di questa iniziativa, il cui spirito era quello di promuovere gli scacchi nella loro forma competitiva verso chi non si era mai cimentato prima nel contesto formale di un torneo. Tutti i giocatori hanno ricevuto un premio di partecipazione in natura e a tutti loro va il nostro incoraggiamento a proseguire e a migliorarsi sempre. Per dovere di cronaca diamo di seguito la classifica finale. 1º classificato Frizzi (9 punti su 9), 2º Turini (7/9), 3º e 3ª <i>ex aequo</i> Gargiulo e Lombardi (6/9), 5º‒6º Baldelli e Graffeo (4/9), 7º Minguzzi (3/9), 8º‒10º Renda, Spagnuolo e Vitiello (2/9).</div><div class=\"collegamentograndecentrato\">Foto\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220018c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_1\']);\">1</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220019c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_2\']);\">2</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220020c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_3\']);\">3</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220023c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_4\']);\">4</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220028c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_5\']);\">5</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220031c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_6\']);\">6</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220033c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_7\']);\">7</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220034c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_8\']);\">8</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220035c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_9\']);\">9</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220036c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_10\']);\">10</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220037c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_11\']);\">11</a> -\n							<a href=\"/Foto/2014-06-22_festival_pisano_dei_giochi_della_mente/P6220039c.JPG\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/foto_festival_giochi_mente_12\']);\">12</a>\n							</div>','torneo-promozionale-alla-stazione-leopolda-2352','2014-06-22 00:00:00',NULL),(2353,1,'Giovanni Innocenti vince il torneo A del 2º torneo weekend Scacchi Sotto la Torre','<div class=\"newstext\">Ottima partecipazione al 2º torneo weekend Scacchi Sotto la Torre, svoltosi presso l\'Hotel Repubblica Marinara nei giorni 11, 12, 13 aprile. La manifestazione ha visto 67 partecipanti che si sono dati battaglia nei tre tornei (torneo A per Elo ≥ 1850, torneo B per Elo compreso fra 1500 e 1899, torneo C per Elo &lt; 1500). Vince il torneo A Giovanni Innocenti da Firenze, seguito dai sardi Luigi Caglio e Damiano Locci. Primi tre classificati nel torneo B sono stati Federico Esposti, Marco Calzolari e Andrea Davini. Sul podio del torneo C sono saliti invece Tommaso Carlesi, Rrapush Lufta e Stefano Esposti.</div><div class=\"collegamentograndecentrato\">Risultati e classifiche</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/torneo-a-elo-ge-1850-2ordm-torneo-weekend-scacchi-sotto-la-torre/\">Torneo A</a></div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/torneo-b-elo-15001899-2ordm-torneo-weekend-scacchi-sotto-la-torre/\">Torneo B</a></div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/torneo-c-under-16-ed-elo-lt-1500-2ordm-torneo-weekend-scacchi-sotto-la-torre/\">Torneo C</a></div>','giovanni-innocenti-vince-il-torneo-a-del-2-torneo-weekend-scacchi-sotto-la-torre-2353','2014-04-14 00:00:00',NULL),(2354,1,'PisaCON e torneo Under 16','<div class=\"newstext\">Il circolo scacchistico \"La Torre\" ha partecipato al <a href=\"http://www.pisacon.it/\">PisaCON</a>, la rassegna dedicata ai giochi da tavolo, di carte e di ruolo che si è svolta alla Stazione Leopolda di Pisa il 15 e 16 marzo 2014. Durante questa manifestazione, la mattina di domenica 16 si è disputato un torneo riservato agli Under 16 e valido per la qualificazione alla Finale nazionale del Campionato Italiano Under 16. Ha vinto Jacopo Riccioli con 3 punti su 5, per spareggio tecnico su Niccolò Ghelardi.</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/wwwGiovanilePisaCON2014/\">Risultati e classifica finale</a></div>','pisacon-e-torneo-under-16-2354','2014-03-16 00:00:00',NULL),(2355,1,'Inizia il corso per adulti','<div class=\"newstext\">È iniziato lunedí 24 febbraio il corso base di scacchi per adulti. Le lezioni tratteranno i <b>principi strategici dell\'apertura</b>, per impostare correttamente la battaglia già dalle primissime mosse, gli <b>elementi della tattica</b>, per imparare a districarsi nelle complicazioni che spesso decidono l\'esito della partita, gli <b>elementi del finale di partita</b>, per imparare a concludere la partita quando sulla scacchiera rimangono solo pochi pezzi.<br>\n							L\'obiettivo del corso è far acquisire al principiante le nozioni fondamentali per giocare bene a scacchi. Il corso sarà strutturato in 8 lezioni da 90 minuti. Si svolgerà ogni lunedí sera dalle 21:00, presso il circolo ARCI L\'Alba, in via delle belle torri, 8. Il costo dell\'intero corso è di 32 euro. Possibilità di adesione anche a corso già iniziato. Per informazioni scrivere a <b>info@scacchilatorre.it</b>.</div>','inizia-il-corso-per-adulti-2355','2014-02-25 00:00:00',NULL),(2356,1,'Leonardo Russo vince il Campionato Provinciale di Pisa Under 16 2014!','<div class=\"newstext\">Sabato 15 febbraio 2014 si è disputato il Campionato Provinciale di Pisa Under 16, valido come prova di qualificazione alla Finale nazionale del Campionato Italiano Under 16, presso il Dopolavoro Ferroviario, in Piazza della Stazione. Hanno partecipato 10 ragazzi. Ha vinto, con un perentorio 5/5, Leonardo Russo, che era anche il numero 1 di tabellone. Secondo posto per Francesco Arsì, con 4 punti; terzo posto con 3 punti per Ersi Gjoni, che si laurea campione provinciale di Pisa Under 16 per il 2014..</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/Provinciale2014_U16/\">Risultati e classifica finale</a></div>','leonardo-russo-vince-il-campionato-provinciale-di-pisa-under-16-2014-2356','2014-02-16 00:00:00',NULL),(2357,1,'Francesco Saverio Rinaldi vince il Campionato Provinciale di Pisa 2014!','<div class=\"newstext\">Si è svolto nei giorni 31 gennaio, 1 e 2 febbraio 2014 il Campionato Provinciale di Pisa, presso la sede del Dopolavoro Ferroviario, in Piazza della Stazione, 16. Presenti 22 giocatori, di tutte le categorie, da Maestro a NC; particolarmente corposa la presenza di questi ultimi, ben 12, alcuni dei quali hanno ottenuto ottimi risultati. Vincitore, con 4,5 punti, il Maestro Francesco Saverio Rinaldi; al secondo posto, con 4 punti, il Candidato Maestro Antonio Pinto; terzo, sempre con 4 punti, si è classificato Alessandro Iraci, al suo primo torneo ma già ottimo protagonista. Lo stesso Iraci e il grossetano Tommaso Carlesi sono stati premiati come migliori NC del torneo.</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/wwwPI2014/\">Risultati e classifica finale</a></div>','francesco-saverio-rinaldi-vince-il-campionato-provinciale-di-pisa-2014-2357','2014-02-02 00:00:00',NULL),(2358,1,'13 dicembre: Francesco Frugoli vince il 10º Semilampo di Pisa','<div class=\"newstext\">Domenica 13 dicembre, nella Sala Convegni della Stazione Leopolda, in Piazza Guerrazzi, si è svolto il 10º Semilampo di Pisa, valido per l\'Elo Rapid FIDE e per il Gran Premio di Toscana. Hanno partecipato 51 giocatori; la vittoria è andata a Francesco Frugoli con 8 punti su 9, precedendo Marco Caprino con 7 e Genci Isufaj con 6,5. Vincitori di fascia Antonio Tacconi (1750-1999), Tommaso Carlesi (1500-1749) e Graziano Furlani (&lt;1500).</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/tournaments/10ordm-torneo-semilampo-di-pisa/\">Risultati e classifica finale</a></div>','13-dicembre-francesco-frugoli-vince-il-10-semilampo-di-pisa-2358','2015-12-13 00:00:00',NULL),(2359,1,'Ripresa degli incontri promozionali','<div class=\"newstext\">Il Circolo Scacchistico \"La Torre\" ha ricominciato la sua attività divulgativa, ricreativa e promozionale. Ci ritroviamo ogni martedì, a partire dal 3 novembre, dalle ore 21 alle 23 presso la <a href=\"http://www.comune.pisa.it/spazi_cittadini/it/dettaglio-spazio-cittadino/22/CTP6-Sala-Riunioni-ex-biblioteca.html\">sala riunioni del CTP 6 (ex biblioteca)</a> a Pisa, in via Contessa Matilde 80. Tutti coloro che volessero venire per imparare a giocare, migliorare, fare qualche partita in compagnia sono i benvenuti.</div>','ripresa-degli-incontri-promozionali-2359','2015-11-03 00:00:00',NULL),(2360,1,'Giulio Calavalle vince il torneo A del 3º torneo weekend Scacchi Sotto la Torre','<div class=\"newstext\">Eccezionale partecipazione al 3º torneo weekend Scacchi Sotto la Torre, svoltosi presso l\'Hotel Repubblica Marinara dal 20 al 22 marzo. La manifestazione ha visto 80 partecipanti divisi nei tornei A (Elo ≥ 1800), B (1440 ≤ Elo &lt; 1850), C/U16 (Elo &lt; 1500). Vince il torneo A il Maestro Giulio Calavalle da Bologna con 4,5 punti, seguito dal Maestro FIDE Alessio De Santis con 4 e dal Maestro Francesco Sonis con 3,5. Si piazzano sul podio del torneo B Yurnio Garcia Rodriguez, Leonardo Russo e Michela Belli, tutti e tre con 4 punti. Primi classificati nel torneo C Guido Bei, Francescantonio Stoduto e Maurizio Massidda, tutti a quota 4 punti.</div><div class=\"collegamentograndecentrato\">Risultati e classifiche</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/torneo-a-elo-ge-1800-3ordm-torneo-weekend-scacchi-sotto-la-torre/\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_3SLT_A\']);\">Torneo A</a></div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/torneo-b-elo-14401849-3ordm-torneo-weekend-scacchi-sotto-la-torre/\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_3SLT_B\']);\">Torneo B</a></div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/torneo-c-under-16-ed-elo-lt-1500-3ordm-torneo-weekend-scacchi-sotto-la-torre/\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_3SLT_C\']);\">Torneo C</a></div>','giulio-calavalle-vince-il-torneo-a-del-3-torneo-weekend-scacchi-sotto-la-torre-2360','2015-03-22 00:00:00',NULL),(2361,1,'Matteo Migliorini vince il Campionato Provinciale di Pisa 2015','<div class=\"newstext\">Si è svolto nei giorni 30 e 31 gennaio e 1º febbraio 2015, nella Sala Convegni della Stazione Leopolda, in Piazza Guerrazzi, il Campionato Provinciale di Pisa. Hanno partecipato 22 giocatori. Vincitore il CM Matteo Migliorini, con 4,5 punti; secondo e campione provinciale Lucio Calcagnile con 4; terzo Marcello Fabbri con 3,5. Vincitori di fascia Tommaso Carlesi (&lt;1700) e Ugo Bindini (&lt;1500).</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/wwwPI2015/\">Risultati e classifica finale</a></div>','matteo-migliorini-vince-il-campionato-provinciale-di-pisa-2015-2361','2015-02-02 00:00:00',NULL),(2362,1,'2 dicembre 2012: Francesco Frugoli vince il 7º Semilampo di Pisa!','<div class=\"newstext\">Ben 57 giocatori hanno preso parte alla settima edizione del tradizionale semilampo di Pisa. Fra questi, tante vecchie conoscenze ma anche tanti scacchisti alle prime esperienze agonistiche. Vince il torneo il candidato maestro lucchese Francesco Frugoli, con 7,5 punti su 9. Si aggiudica il secondo posto Franco Baccaro, candidato maestro di Firenze, con 7 punti, mentre al terzo posto si piazza il maestro FIDE Claudio Evangelisti di Pisa, anch\'egli con 7 punti. Primi classificati delle fasce Elo 1750-1999, 1500-1749, &lt;1500, rispettivamente Francesco Salerno, Luca Onesti e Fabrizio D\'Alessandro.</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/SemilampoPisa2012/index.html\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_7º_torneo_semilampo\']);\">Risultati e classifica finale</a></div>','2-dicembre-2012-francesco-frugoli-vince-il-7-semilampo-di-pisa-2362','2012-12-02 00:00:00',NULL),(2363,1,'18 novembre 2012: inizia il tesseramento per il 2013','<div class=\"newstext\">A partire dal 1º dicembre è possibile richiedere alla Federazione le tessere per l\'attività agonistica del 2013. Esse hanno validità anche per tutte le competizioni di dicembre 2012 e possono pertanto essere sfruttate tredici mesi. Nell\'apposita pagina sul <a href=\"tesseramento2013.php\">tesseramento 2013</a> sono illustrati i vari tipi di tesseramento possibili. Il <a href=\"/bandi/Bando_PisaDic2012.pdf\">7º torneo semilampo di Pisa</a> del 2 dicembre prossimo è un\'occasione ghiotta per chi volesse cominciare (o riprendere) l\'attività agonistica dei tornei. La tessera si può richiedere in sede di torneo.</div>','18-novembre-2012-inizia-il-tesseramento-per-il-2013-2363','2012-11-18 00:00:00',NULL),(2364,1,'15 ottobre 2012: il 2 dicembre settima edizione del Semilampo di Pisa!','<div class=\"newstext\">Domenica 2 dicembre, presso l\'Hotel Repubblica Marinara, via Matteucci, 81, si svolgerà il settimo appuntamento col tradizionale Semilampo di Pisa. Come sempre, il torneo è articolato su 9 turni, mentre il tempo sarà di 12\' + 5\" a mossa. Primo premio € 130,00, premi per i primi 5 classificati, per le fasce U2000, U1750 e U1500, per under 16, over 60 e donne. Potete trovare il bando del torneo <a href=\"/bandi/Bando_PisaDic2012.pdf\">qui</a>. Iscrizioni € 15,00 (€ 10,00 per i nati dopo il 31/12/1995 e NC). Preiscrizioni tramite l\'apposita <a href=\"http://vesus.org/tornei/7ordm-torneo-semilampo-di-pisa/\">pagina</a> del sito VeSuS, email o telefono (recapiti nella colonna di sinistra sotto \"Contatti:\"). Vi aspettiamo numerosi!</div>','15-ottobre-2012-il-2-dicembre-settima-edizione-del-semilampo-di-pisa-2364','2012-10-15 00:00:00',NULL),(2365,1,'11 ottobre 2012: inizia il corso sul mediogioco','<div class=\"newstext\">Inizia a breve il corso sul mediogioco negli scacchi tenuto dal Maestro Francesco Saverio Rinaldi, istruttore federale. Il corso è rivolto a chi desidera approfondire la conoscenza degli elementi importanti di tattica e di strategia per migliorare sensibilmente il proprio livello di gioco. Ecco il <a href=\"/file/programmacorsomediogiuoco.pdf\">programma</a>. Il corso, che si compone di 8 lezioni da 90 minuti ciascuna, si terrà ogni lunedì sera dalle 20:30 alle 22:00 presso il circolo ARCI L\'Alba, in via delle Belle Torri, 8. Al termine di ogni lezione i partecipanti potranno giocare liberamente per esercitarsi. Il costo complessivo è di 40 € a persona. Per informazioni e prenotazioni chiamare il docente al numero 3311336695 o scrivere a info@scacchilatorre.it.</div>','11-ottobre-2012-inizia-il-corso-sul-mediogioco-2365','2012-10-11 00:00:00',NULL),(2366,1,'28 settembre 2012: inizia il corso per bambini','<div class=\"newstext\">Da sabato 6 ottobre si terrà presso i locali del DLF in Piazza della Stazione, 16 il corso di scacchi per bambini tenuto dal Maestro Francesco S. Rinaldi, istruttore federale. Il corso si terrà ogni sabato dalle 15:30 alle 17:30 e durerà fino a febbraio (minimo 40 ore). Il costo è di 70 € per tutto il corso a bambino, con sconto del 50% su un eventuale secondo membro familiare. È possibile iscriversi anche dopo l\'inizio del corso. Per ulteriori informazioni, contattare il docente al numero 3311336695.</div>','28-settembre-2012-inizia-il-corso-per-bambini-2366','2012-09-28 00:00:00',NULL),(2367,1,'21 maggio 2012: Campionato Regionale Toscano 2012','<div class=\"newstext\">Si è disputato a Firenze, nei giorni 18, 19, 20 maggio, il Campionato Regionale Toscano 2012. La partecipazione è stata numerosa, con 43 giocatori che hanno preso parte al torneo, di cui ben sette tesserati col Circolo Scacchistico La Torre: Lucio Calcagnile, Michele Casarosa, Paolo Cerri, Marco Montesanti, Alice Nocera, Antonio Pinto e Rosario Rizza. È da segnalare l\'ottimo risultato di Rosario, che guadagna 51 punti Elo e conquista virtualmente la 2ª categoria nazionale, realizzando anche una <i>tranche</i> FIDE di 1928 punti Elo! Il podio del torneo: 1º Riccardo Bisignano, 2º Edoardo Cocuzzi, 3º Doriano Tocchioni. Tutti i risultati e le classifiche <a href=\"http://xoomer.alice.it/dlf/Tornei2012/wwwCRT12/\">qui</a>.</div>','21-maggio-2012-campionato-regionale-toscano-2012-2367','2012-05-21 00:00:00',NULL),(2368,1,'18 maggio 2012: buon successo del lampo promozionale alle Piagge!','<div class=\"newstext\">16 giocatori hanno preso parte al torneo lampo promozionale organizzato dal Circolo Scacchistico La Torre alle Piagge. Il livello del torneo si è rivelato abbastanza alto, grazie anche alla presenza di alcune vecchie conoscenze. Siamo molto contenti della partecipazione di tanti volti nuovi, molti dei quali alle prese con la loro prima esperienza agonistica. A loro rivolgiamo l\'incoraggiamento a proseguire e l\'augurio di diventare forti. La vittoria del torneo è andata a Marco Messina, con 7,5 punti su 8. Secondo classificato Stanisa Raspopovic, con 6,5 punti, terzo classificato Adriano Cappagli, con 6 punti. Classifiche e risultati <a href=\"/tornei/wwwLampoSUbaldo/\">qui</a>.</div>','18-maggio-2012-buon-successo-del-lampo-promozionale-alle-piagge-2368','2012-05-18 00:00:00',NULL),(2369,1,'13 maggio 2012: torneo lampo promozionale alle Piagge!','<div class=\"newstext\">In occasione della Festa di Sant\'Ubaldo – XXXIII Settimana alle Piagge, il circolo \"La Torre\" organizza un <strong>torneo lampo promozionale</strong>, che si terrà presso il centro espositivo San Michele degli Scalzi, in viale delle Piagge, la sera di <strong>giovedì 17 maggio</strong> dalle ore 21 alle 23:30. È incoraggiata la partecipazione di principianti, amatori e semplici appassionati che vogliano provare a giocare in un contesto un po\' più agonistico di una partita fra amici. Il torneo si svolgerà su 8 turni, con tempo di riflessione di 5 minuti a giocatore. Iscrizione 3 euro, premi in materiale scacchistico (anche a estrazione).</div>','13-maggio-2012-torneo-lampo-promozionale-alle-piagge-2369','2012-05-13 00:00:00',NULL),(2370,1,'25 febbraio 2012: buon successo del semilampo al PisaCON!','<div class=\"newstext\">16 partecipanti hanno giocato il semilampo promozionale organizzato presso il PisaCON dal circolo \"La Torre\" e dagli <a href=\"http://www.scacchinsorgenti.com/\">Scacchi Insorgenti</a>. La vittoria è andata a Pierluigi Pellizzer, con 4,5 punti su 5; secondo classificato Tony Spinelli, terzo Stefano Maggiolo. Tutti i risultati e le classifiche <a href=\"/tornei/wwwSemilampo/\">qui</a>.</div>','25-febbraio-2012-buon-successo-del-semilampo-al-pisacon-2370','2012-02-25 00:00:00',NULL),(2371,1,'15 febbraio 2012: il circolo \"La Torre\" al PisaCON!','<div class=\"newstext\">Il Circolo Scacchistico La Torre prende parte alla manifestazione ludica <a href=\"http://www.pisacon.it/\"><strong>PisaCON</strong></a>, che si svolgerà presso la Stazione Leopolda nei giorni <strong>sabato 25</strong> (ore 10-24) e <strong>domenica 26</strong> (ore 10-22) febbraio. Organizziamo un <strong>torneo promozionale</strong>, dedicato agli amanti degli scacchi che vogliano provare l\'emozione di un torneo. Non occorre affatto essere dei campioni, basta essere degli appassionati. Lo scopo di questo torneo è dare la possibilità ai partecipanti di confrontarsi con altri giocatori in un contesto un po\' più formale di un incontro fra amici. Saranno distribuiti anche premi in materiale scacchistico a estrazione fra tutti i partecipanti. A fine torneo verrà fornita a ciascun partecipante una stima del proprio punteggio Elo. Organizziamo anche una <strong>simultanea</strong> e un <strong>concorso di risoluzione di problemi di scacchi</strong>. Leggi <a href=\"/bandi/scacchi_PisaCON_2012.pdf\">qui</a> il bando di questi eventi per conoscerne i dettagli. Segnalaci <a href=\"preiscrizione.html\">qui</a> la tua intenzione di partecipare al torneo per essere sicuro di trovare posto (puoi leggere <a href=\"lista_preiscritti.php\">qui</a> la lista dei preiscritti). Saremo presenti nel nostro spazio espositivo per tutta la durata della manifestazione. Passa a trovarci se vuoi imparare a giocare, se vuoi consigli su come migliorare, se vuoi informazioni sull\'attività del circolo e sugli eventi scacchistici in Toscana.</div>','15-febbraio-2012-il-circolo-la-torre-al-pisacon-2371','2012-02-15 00:00:00',NULL),(2372,1,'29 gennaio 2012: Antonio Pinto Campione Provinciale Pisano 2012!','<div class=\"newstext\">Il CM Antonio Pinto, con 6 vittorie su 6 partite, si aggiudica il Campionato Provinciale Pisano 2012, nonché il titolo di campione Provinciale Pisano 2012. Secondo posto per Marco Messina con 4,5 punti, terzo Mauro Nervi con 4. Rosario Rizza primo fra gli Under 1800, mentre Paolo Cerri si aggiudica il premio per il miglior Under 1500. 14 i partecipanti. <a href=\"/tornei/wwwPI2012\">Qui</a> i risultati di tutti i turni e la classifica finale completa.</div>','29-gennaio-2012-antonio-pinto-campione-provinciale-pisano-2012-2372','2012-01-29 00:00:00',NULL),(2373,1,'31 dicembre: online il bando del Campionato Provinciale di Pisa 2012!','<div class=\"newstext\">Si svolgerà nei giorni 21, 22, 28 e 29 gennaio 2012 il Campionato Provinciale di Pisa. La sede di gioco, come già da alcuni anni, sarà la Sala Soci della COOP, in via Walter Tobagi, 1. Il torneo è valido ome Ottavi di Finale del Campionato Italiano Assoluto 2012 e permette la qualificazione ai Quarti di finale (Campionato Regionale) agli iscritti a un circolo della Provincia di Pisa. Il torneo si giocherà su 6 turni con un tempo di riflessione di 100\' a testa + 30\" di abbuono per mossa. La novità di quest\'anno è la convenzione con il Provinciale di Livorno del 13-15 gennaio: chi disputerà entrambi i tornei avrà diritto a una riduzione di € 5,00 su ciascuna iscrizione (€ 10,00 in totale). <a href=\"/bandi/ProvPisa2012.pdf\">Qui</a> è disponibile il bando. Preiscrizioni tramite l\'apposita <a href=\"http://vesus.org/tornei/campionato-provinciale-di-pisa-2012/\">pagina</a> del sito VeSuS, email o telefono (recapiti nella colonna di sinistra sotto \"Contatti:\").</div>','31-dicembre-online-il-bando-del-campionato-provinciale-di-pisa-2012-2373','2012-12-31 00:00:00',NULL),(2374,1,'Duilio Collutiis vince l\'ottava edizione del Semilampo di Pisa!','<div class=\"newstext\">Domenica 1º dicembre, presso l\'Hotel Repubblica Marinara, via Matteucci, 81, si è svolto l\'ottavo appuntamento col tradizionale Semilampo di Pisa. Hanno partecipato 53 giocatori di ogni livello, da Maestro Internazionale a non classificato, provenienti da ogni parte d\'Italia. Il torneo è stato vinto dal MI Duilio Collutiis, con 8 punti su 9; al secondo posto il CM Francesco Frugoli, vincitore l\'anno scorso, con 7; al terzo il CM Franco Baccaro, piazzatosi secondo l\'anno scorso, con 6,5. Vincitori di fascia Fabio Magini (1750-1999), Ermanno Pacini (1500-1749) e Michael Antonio Gargiulo (≤1500).</div><div class=\"collegamentograndecentrato\"><a href=\"/tornei/SemilampoPisa2013/\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_semilampo_1dic2013\']);\">Risultati e classifica finale</a></div>','duilio-collutiis-vince-lottava-edizione-del-semilampo-di-pisa-2374','2013-12-01 00:00:00',NULL),(2375,1,'Corso di scacchi per bambini e ragazzi dai 7 ai 15 anni','<div class=\"newstext\">È iniziata sabato 5 ottobre, presso i locali del dopolavoro ferroviario, la <a href=\"/file/locandina_corsoscacchi.jpg\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/locandina_scuolascacchi\']);\">scuola di scacchi</a> per bambini e ragazzi dai 7 ai 15 anni. Il corso è articolato in due moduli, di quattro mesi ciascuno. È possibile iscriversi in qualunque momento. Prima lezione gratuita. Per informazioni contattare l\'istruttore Francesco Saverio Rinaldi (recapiti nella <a href=\"/file/locandina_corsoscacchi.jpg\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/locandina_corsoscacchi\']);\">locandina</a>).</div>','corso-di-scacchi-per-bambini-e-ragazzi-dai-7-ai-15-anni-2375','2013-10-31 00:00:00',NULL),(2376,1,'Torneo Giovanile a Pisa','<div class=\"newstext\">Numerosi giovani scacchisti, fra cui una folta spedizione grossetana, hanno preso parte al torneo giovanile disputatosi il 16 marzo a Pisa presso il Dopolavoro Ferroviario. Fra i 22 partecipanti esce vincitore incontrastato il grossetano Leonardo Russo, a punteggio pieno con 5/5. Secondo classificato il pisano Marco Pellegrini, con 4 punti; terzo classificato Filippo Marzinotto, da Grosseto, con 4 punti. Risultati e classifiche del torneo <a href=\"/tornei/U16-20130316/index.html\">qui</a>.</div>','torneo-giovanile-a-pisa-2376','2013-03-17 00:00:00',NULL),(2377,1,'Jacopo Lussetti vince il Campionato Provinciale Pisano Under 16','<div class=\"newstext\">13 giocatori hanno partecipato al Campionato Provinciale Pisano Under 16, svoltosi a Pisa, presso i locali del Dopolavoro Ferroviario, il 2 febbraio 1013. Vincitore il grossetano Jacopo Lussetti, con 5 punti su 6; secondo Andrea Targetti, con 4 punti, mentre terzo e campione provinciale, Marco Pellegrini, con 3,5 punti. Risultati e classifiche del torneo <a href=\"/tornei/Provinciale2013_U16\">qui</a>.</div>','jacopo-lussetti-vince-il-campionato-provinciale-pisano-under-16-2377','2013-02-27 00:00:00',NULL),(2378,1,'Torneo promozionale e simultanea alla Stazione Leopolda (23-24 febbraio 2013)','<div class=\"newstext\">Sabato 23 e domenica 24 febbraio siamo alla manifestazione ludica <a href=\"http://www.pisacon.it/\"><strong>PisaCON</strong></a>, presso la Stazione Leopolda, con uno spazio dedicato agli scacchi. Per sabato (dalle 15 alle 17) è previsto un torneo promozionale, mentre per domenica (dalle 14 alle 16) una simultanea in cui uno scacchista esperto sfiderà 8 giocatori contemporaneamente. La partecipazione è libera. Saremo inoltre presenti insieme agli <a href=\"http://www.scacchinsorgenti.com\">Scacchi Insorgenti</a> nel nostro spazio espositivo per tutta la durata della manifestazione. Passa a trovarci se vuoi imparare a giocare, se vuoi consigli su come migliorare, se vuoi informazioni sull\'attività del circolo e sugli eventi scacchistici in Toscana.</div>','torneo-promozionale-e-simultanea-alla-stazione-leopolda-23-24-febbraio-2013-2378','2013-02-10 00:00:00',NULL),(2379,1,'1º torneo weekend \"Sotto la Torre\" (15-16-17 febbraio 2013)','<div class=\"newstext\">54 giocatori hanno partecipato al 1º torneo weekend \"Sotto la Torre\", svoltosi a Pisa nei giorni 15, 16, 17 febbraio 2013, presso l\'Hotel Repubblica Marinara. I giocatori provenivano per lo più dalla Toscana, ma una buona risposta è arrivata anche da altre parti d\'Italia, anche lontane. Molto gradita la presenza giovanile, con un buon numero di bambini e ragazzi provenienti anch\'essi da tutta Italia. Il torneo A è stato vinto dal MF pisano Marco Codenotti, che ha sbaragliato il campo con un inequivocabile 5 su 5. Marco con questa prestazione supera i 2400 punti Elo FIDE, conquistando così il titolo di Maestro Internazionale. Siamo davvero felici di aver potuto dare noi questa notizia, visto che Marco è scacchisticamente cresciuto a Pisa ed è a tutti gli effetti uno di noi. Gli rinnoviamo i nostri complimenti e gli auguri di una carriera ancor più brillante. Al secondo posto il CM Francesco Frugoli, mentre al terzo il CM Massimo La Rosa. Il torneo B è stato vinto da Maria Palma, davanti a Stefano Osimanti e Yurnio Garcia Rodriguez.</div><div class=\"collegamentograndecentrato\">Risultati e classifiche finali     <a href=\"/tornei/SottolaTorre2013/Open_A/index.html\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_Open_A\']);\">Open A</a>  <a href=\"/tornei/SottolaTorre2013/Open_B/index.html\" onclick=\"javascript: _gaq.push([\'_trackPageview\', \'/risultati_Open_B\']);\">Open B</a></div>','1-torneo-weekend-sotto-la-torre-15-16-17-febbraio-2013-2379','2013-02-18 00:00:00',NULL),(2380,1,'Campionato Provinciale Pisano Under 16','<div class=\"newstext\">Sabato 2 febbraio 2013 si disputerà il Campionato Provinciale Pisano Under 16, valido come prova di qualificazione alla Finale nazionale del Campionato Italiano Under 16. La sede è il Dopolavoro Ferroviario, in Piazza della Stazione. Informazioni e preiscrizioni nel <a href=\"/bandi/provincialeu16_2013.pdf\">bando</a>.</div>','campionato-provinciale-pisano-under-16-2380','2013-01-24 00:00:00',NULL),(2381,1,'Partono i corsi di scacchi 2023 per adulti e ragazzi!','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">A febbraio 2023 inizieranno i nuovi corsi di scacchi per adulti e ragazzi fra gli 8 e i 18 anni. Per gli adulti sono previsti un corso di primo livello e uno di secondo livello. Iscrizioni entro gennaio. Maggiori dettagli nella locandina. Informazioni su costi e orari via email.</div><div class=\"collegamentograndecentrato\"><a href=\"/file/locandina_corsi_scacchi_2023.jpg\"><img src=\"file/locandina_corsi_scacchi_2023.jpg\" width=\"50%\" border=\"2\"></a></div>','partono-i-corsi-di-scacchi-2023-per-adulti-e-ragazzi-2381','2022-12-21 00:00:00',NULL),(2382,1,'Tesseramento FSI 2023','<div class=\"newstext\">Parte il <a href=\"tesseramento2023.php\">tesseramento FSI</a> per il 2023 per disputare tornei e campionati.</div>','tesseramento-fsi-2023-2382','2022-12-01 00:00:00',NULL),(2383,1,'5º torneo weekend Scacchi Sotto la Torre','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Si è tenuto a Pisa i giorni <b>21, 22, 23 ottobre 2022</b>, presso la Stazione Leopolda, il <b>5º torneo weekend Scacchi Sotto la Torre</b>, suddiviso in torneo A (Elo ≥ 1600) e torneo B (Elo ≤ 1700).</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Nel torneo A (14 partecipanti) vince il CM <b>Fausto Calandri</b> con 4,5 punti su 5. Secondo classificato il CM <b>Lucio Calcagnile</b> con 3,5 punti. Chiude il podio il M <b>Enrico Pepino</b> con 3 punti. Quarto classificato <b>Kai Neubauer</b>, quinto classificato e vincitore della fascia Elo Leonardo Mazzi.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Nel torneo B (20 partecipanti) vince a punteggio pieno con cinque vittorie su cinque partite <b>Lorenzo Botindari</b>. Al secondo posto <b>Alessio Loi</b> (4 punti), al terzo <b>Mario Cappellari</b> (3,5 punti), al quarto (1º Elo Giuseppe Palaia.</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/results/torneo-a-elo-ge-1600-5ordm-torneo-weekend-scacchi-sotto-la-torre/standing/\" target=\"_blank\">Risultati torneo A</a></div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/results/torneo-b-elo-le-1700-5ordm-torneo-weekend-scacchi-sotto-la-torre/standing/\" target=\"_blank\">Risultati torneo B</a></div><div class=\"collegamentograndecentrato\"><a href=\"/foto/2022-10_SSLT/2.jpg\"><img src=\"/foto/2022-10_SSLT/2.jpg\" width=\"32%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/3.jpg\"><img src=\"/foto/2022-10_SSLT/3.jpg\" width=\"32%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/4.jpg\"><img src=\"/foto/2022-10_SSLT/4.jpg\" width=\"32%\" border=\"1\"></a></div><div class=\"collegamentograndecentrato\"><a href=\"/foto/2022-10_SSLT/5.jpg\"><img src=\"/foto/2022-10_SSLT/5.jpg\" width=\"32%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/6.jpg\"><img src=\"/foto/2022-10_SSLT/6.jpg\" width=\"32%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/7.jpg\"><img src=\"/foto/2022-10_SSLT/7.jpg\" width=\"32%\" border=\"1\"></a></div><div class=\"collegamentograndecentrato\"><a href=\"/foto/2022-10_SSLT/8.jpg\"><img src=\"/foto/2022-10_SSLT/8.jpg\" width=\"32%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/9.jpg\"><img src=\"/foto/2022-10_SSLT/9.jpg\" width=\"32%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/a.jpg\"><img src=\"/foto/2022-10_SSLT/a.jpg\" width=\"32%\" border=\"1\"></a></div><div class=\"collegamentograndecentrato\"><a href=\"/foto/2022-10_SSLT/1.jpg\"><img src=\"/foto/2022-10_SSLT/1.jpg\" width=\"20%\" border=\"1\"></a><a href=\"/foto/2022-10_SSLT/b.jpg\"><img src=\"/foto/2022-10_SSLT/b.jpg\" width=\"40%\" border=\"1\"></a></div>','5-torneo-weekend-scacchi-sotto-la-torre-2383','2022-10-24 00:00:00',NULL),(2384,1,'Torneino e simultanea di fine corso','<div class=\"newstext\">Un torneino di quattro turni e una simultanea del MF Pierluigi Passerotti (otto vittorie e una patta) hanno chiuso oggi i corsi di scacchi, di livello base e avanzato, iniziati a febbraio. Protagonisti di questo bel pomeriggio di scacchi sono stati alcuni degli allievi e qualche ospite estemporaneo.</div><div class=\"newstext\">Complimenti a tutti e alla prossima!</div><div class=\"collegamentograndecentrato\"><a href=\"/pics/2022-05-21_12.jpg\"><img src=\"/pics/2022-05-21_12.jpg\" width=\"49%\" border=\"1\"></a><a href=\"/pics/2022-05-21_13.jpg\"><img src=\"/pics/2022-05-21_13.jpg\" width=\"49%\" border=\"1\"></a></div>','torneino-e-simultanea-di-fine-corso-2384','2022-05-21 00:00:00',NULL),(2385,1,'Il MI Pierluigi Piscopo al Circolo di Pisa','<div class=\"newstext\">Il MI Pierluigi Piscopo, ospite oggi pomeriggio del Circolo Scacchistico “La Torre”, ha offerto ai presenti una bellissima lezione su come sfruttare, con entrambi i colori, le potenzialità di una struttura pedonale centrale comunissima nella difesa Siciliana.</div><div class=\"newstext\">Un caloroso ringraziamento al Maestro Piscopo, che con la sua competenza e le sue grandi capacità d\'istruttore ci ha fatto entrare in profondità nelle strategie che emergono da un\'apertura fra le piú affascinanti.</div><div class=\"newstext\">Grazie al Comitato Regionale Toscano, organizzatore e sostenitore di questa iniziativa cui siamo stati felicissimi di aderire.</div><div class=\"newstext\">Grazie a tutti gli intervenuti, soci del circolo e no, per la partecipazione e l\'interesse dimostrato.</div><div class=\"newstext\">[In foto, Pierluigi Passerotti (CRT) introduce la conferenza/lezione di Piscopo.]</div><div class=\"collegamentograndecentrato\"><a href=\"/pics/2022-05-10_conferenzaPiscopo1.jpeg\"><img src=\"/pics/2022-05-10_conferenzaPiscopo1.jpeg\" width=\"49%\" border=\"1\"></a><a href=\"/pics/2022-05-10_conferenzaPiscopo2.jpeg\"><img src=\"/pics/2022-05-10_conferenzaPiscopo2.jpeg\" width=\"49%\" border=\"1\"></a></div>','il-mi-pierluigi-piscopo-al-circolo-di-pisa-2385','2022-05-10 00:00:00',NULL),(2386,1,'Conferenza del MI Pierluigi Piscopo sulla difesa Siciliana al Circolo di Pisa!','<div class=\"newstext\">Martedì 10 maggio, dalle 16 alle 19, il <b>MI Pierluigi Piscopo</b> sarà ospite del Circolo Scacchistico “La Torre” per una conferenza sulla difesa Siciliana. Piscopo, scacchista dal gioco brillante e eccezionale istruttore, ci accompagnerà alla scoperta di un\'apertura affascinante come poche. Tutti i soci, gli amici e gli appassionati sono invitati. L\'appuntamento è per <b>martedì 10 maggio</b>, dalle 16 alle 19, presso la Sala Convegni della <b>Stazione Leopolda</b> (ingresso via Francesco da Buti). L\'evento è gratuito. L\'iniziativa è organizzata e sponsorizzata dal <a href=\"http://www.toscanascacchi.it/\">Comitato Regionale Toscano</a>.</div>','conferenza-del-mi-pierluigi-piscopo-sulla-difesa-siciliana-al-circolo-di-pisa-2386','2022-05-01 00:00:00',NULL),(2387,1,'Tesseramento FSI 2024','<div class=\"newstext\">Parte il <a href=\"tesseramento2024.php\">tesseramento FSI</a> per il 2024 per disputare tornei e campionati.</div>','tesseramento-fsi-2024-2387','2023-12-01 00:00:00',NULL),(2388,1,'Nuovo appuntamento settimanale: torneo su Lichess','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\"><b>Ogni domenica sera</b>, a partire da domenica 5 novembre, alle <b>ore 21:15</b>, giocheremo un <b>torneo su Lichess</b>. La partecipazione è aperta a tutti gli iscritti del nostro circolo. Basta andare su Lichess, iscriversi al <a href=\"https://lichess.org/team/circolo-scacchistico-la-torre-pisa\">nostro gruppo</a> (specificate il vostro nome nella richiesta di adesione) e iscriversi al torneo, il cui link apparirà nella pagina del gruppo. Tornei già in programma: <a href=\"https://lichess.org/tournament/33coCcqU\">Domenica 5 novembre: Arena 10\'+5\"</a>, <a href=\"https://lichess.org/tournament/VbUF5kNz\">Domenica 12 novembre: Arena 8\'+10\"</a>, <a href=\"https://lichess.org/tournament/oAz6miif\">Domenica 19 novembre: Arena 15\'+5\"</a>. Buon gioco!</div>','nuovo-appuntamento-settimanale-torneo-su-lichess-2388','2023-11-04 00:00:00',NULL),(2389,1,'6º torneo weekend Scacchi sotto la Torre','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Ottima partecipazione al <b>6º torneo weekend Scacchi sotto la Torre</b> svoltosi i giorni <b>21–22 ottobre</b> presso la Sala Convegni della Stazione Leopolda.<p>Il <b>torneo A</b> (1500 ≤ Elo ≤ 2399) ha visto darsi battaglia 18 partecipanti: 1º classificato il polacco <b>Michał Mirski</b> (4,5/5), 2º classificato 1N <b>Pietro Vetturi</b> (3,5/5), 3º classificato 2N <b>Federico Santoni</b> (3,5/5). Primo classificato della fascia Elo Francesco Saverio Valgimigli.</p><p>Al <b>torneo B</b> (Elo Martino Salbego (5/5), 2º classificato <b>Gerardo Jose Cammarano</b> (4/5), 3º classificato <b>Liu Jiabao</b> (4/5). Quarto classificato, a lungo in lizza per il podio e premiato come miglior under 18, il quattordicenne <b>Leandro Trincherini</b>.</p></div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/ZMQw4HwI\">Risultati e classifiche</a></div>','6-torneo-weekend-scacchi-sotto-la-torre-2389','2023-10-23 00:00:00',NULL),(2390,1,'Inizio corsi di scacchi per ragazzi (6-18 anni)','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Riparte la scuola di scacchi per bambini e ragazzi dai 6 ai 18 anni. Primo appuntamento il 7 ottobre. Tutti i dettagli nella locandina, iscrizioni e ulteriori informazioni per email.</div><div class=\"collegamentograndecentrato\"><a href=\"/corsi/2023-ott-dic_scuola-scacchi-ragazzi-6-18anni.pdf\"><img src=\"/corsi/2023-ott-dic_scuola-scacchi-ragazzi-6-18anni.jpg\" width=\"50%\" border=\"2\"></a></div>','inizio-corsi-di-scacchi-per-ragazzi-6-18-anni-2390','2023-09-22 00:00:00',NULL),(2391,1,'Torneino al circolo, giovedì 28 settembre','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Giovedì 28 settembre al circolo torneo rapid amichevole riservato ai soci.<br>Sede di gioco: largo Petrarca, 3, Pisa<br>Orario di inizio: 21:00<br>Numero turni: 5<br>Tempo di riflessione: 12\' + 3\"<br>Quota di iscrizione: 3 euro<br>Numero massimo giocatori: 24<br>Premi in natura al miglior 30% dei giocatori circa.<br>Possibilità di regolarizzare la posizione di socio versando prima del torneo la quota associativa annua di 10 euro.</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/tournament/0TRmyL_t\">Risultati</a></div>','torneino-al-circolo-giovedi-28-settembre-2391','2023-09-24 00:00:00',NULL),(2392,1,'Notte bianca dello sport: sabato 23 settembre','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Dalle 18:30 alle 22:30 di sabato 23 settembre saremo a fianco alle Logge di Banchi con uno spazio per il gioco libero e un banchetto informativo. Dalle 19 alle 20 si terrà una simultanea col Maestro FIDE Claudio Evangelisti. Venite a trovarci!</div><div class=\"collegamentograndecentrato\"><a href=\"/eventi/2023-09-23_Notte-bianca-dello-sport_Brochure-programma-1.jpg\"><img src=\"/eventi/2023-09-23_Notte-bianca-dello-sport_Brochure-programma-1.jpg\" width=\"49%\" border=\"2\"></a><a href=\"/eventi/2023-09-23_Notte-bianca-dello-sport_Brochure-programma-2.jpg\"><img src=\"/eventi/2023-09-23_Notte-bianca-dello-sport_Brochure-programma-2.jpg\" width=\"49%\" border=\"2\"></a></div>','notte-bianca-dello-sport-sabato-23-settembre-2392','2023-09-22 00:00:00',NULL),(2393,1,'Riprendono i giovedì al circolo','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Da giovedì 14 settembre riprendono gli incontri settimanali di gioco libero per i soci del circolo. La sede di gioco è sempre in Largo Petrarca 3, nei locali dell\'ex Circoscrizione CTP 5. Continuano anche gli incontri aperti a tutti del lunedì sera al Café Albatross, in via Cavalca 64. Tutti gli incontri sono a ingresso libero e iniziano intorno alle 21:30. Chiunque sia interessato è invitato a partecipare.</div>','riprendono-i-giovedi-al-circolo-2393','2023-09-13 00:00:00',NULL),(2394,1,'Il giovedì al circolo fino a fine luglio','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Il ritrovo settimanale del giovedì sera continua fino a fine luglio, poi seguirà una sospensione di tutte le attività nel mese di agosto e la ripresa a settembre.</div>','il-giovedi-al-circolo-fino-a-fine-luglio-2394','2023-06-13 00:00:00',NULL),(2395,1,'Torneo di fine corso per bambini e ragazzi','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Sabato 10 giugno si sono conclusi i corsi di scacchi per bambini e ragazzi con un torneo amichevole di fine corso, cui hanno partecipato 10 bambini del primo corso e 4 ragazzi del secondo. Arrivederci all\'autunno con l\'inizio dei nuovi corsi e buona estate a tutti gli allievi!</div><div class=\"collegamentograndecentrato\"><a href=\"/foto/2023-06-10_torneo-di-fine-corso.jpg\"><img src=\"foto/2023-06-10_torneo-di-fine-corso.jpg\" width=\"50%\" border=\"2\"></a></div>','torneo-di-fine-corso-per-bambini-e-ragazzi-2395','2023-06-11 00:00:00',NULL),(2396,1,'Risultati finali e classifica slam scacchistico','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Si è concluso ieri, 25 maggio, il 1º minislam scacchistico, al quale hanno preso parte complessivamente 26 giocatori, fra i quali diverse facce nuove. Per la classifica finale vengono sommati i punti ottenuti nelle due migliori prove. Premiati con prodotti alimentari i primi sette classificati. Vince il titolo di campione studentesco Gioele Villino, secondo classificato assoluto.</div><div class=\"collegamentograndecentrato\"><a href=\"/foto/2023-05_classifica-minislam.jpeg\"><img src=\"foto/2023-05_classifica-minislam.jpeg\" width=\"50%\" border=\"2\"></a></div>','risultati-finali-e-classifica-slam-scacchistico-2396','2023-05-26 00:00:00',NULL),(2397,1,'Slam scacchistico','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Nei giorni <b>11, 18, 25 maggio</b> si svolgeranno tre tornei presso la sede del circolo (5 turni, tempo di riflessione 12\'+3\", inizio ore 21:00, capienza massima 20 partecipanti), valevoli per un minislam scacchistico. Tornei non validi per le variazioni Elo. Non è richiesta la tessera FSI. È richiesto essere in regola con la quota associativa 2023 del Circolo (possibilità di associarsi o rinnovare la quota annuale in sede, costo 10 euro). Quota d\'iscrizione per ogni torneo 3 euro. Premi in natura ai primi classificati di ogni singola prova, ai primi classificati dello slam generale e al campione studentesco. Ai fini della classifica generale verranno conteggiate le 2 migliori prestazioni su 3. Iscrizioni e risultati su Vesus:</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/tournament/G5jyqkyJ\">vesus.org/tournament/G5jyqkyJ</a> (11 maggio)   (foto <a href=\"/foto/2023-05-11_minislam-1a-prova/1.jpeg\">1</a> - <a href=\"/foto/2023-05-11_minislam-1a-prova/2.jpeg\">2</a> - <a href=\"/foto/2023-05-11_minislam-1a-prova/3.jpeg\">3</a>)</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/tournament/iRHto46o\">vesus.org/tournament/iRHto46o</a> (18 maggio)   (foto <a href=\"/foto/2023-05-18_minislam-2a-prova/1.jpeg\">1</a> - <a href=\"/foto/2023-05-18_minislam-2a-prova/2.jpeg\">2</a> - <a href=\"/foto/2023-05-18_minislam-2a-prova/3.jpeg\">3</a>)</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/tournament/rOlbd8r1\">vesus.org/tournament/rOlbd8r1</a> (25 maggio)   (foto <a href=\"/foto/2023-05-25_minislam-3a-prova/1.jpeg\">1</a> - <a href=\"/foto/2023-05-25_minislam-3a-prova/2.jpeg\">2</a> - <a href=\"/foto/2023-05-25_minislam-3a-prova/3.jpeg\">3</a>)</div><div class=\"collegamentograndecentrato\"><a href=\"/bandi/slam-scacchistico-maggio-2023.png\"><img src=\"bandi/slam-scacchistico-maggio-2023.png\" width=\"50%\" border=\"2\"></a></div>','slam-scacchistico-2397','2023-05-02 00:00:00',NULL),(2398,1,'Rinvio 8ª lezione corso adulti 1º livello','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">L\'ottava lezione del corso di scacchi di 1º livello non si terrà sabato 15 aprile ma è rinviata a sabato 22 aprile, solito orario.</div>','rinvio-8-lezione-corso-adulti-1-livello-2398','2023-04-13 00:00:00',NULL),(2399,1,'Sospensione attività fino a Pasqua','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Le attività del circolo (ritrovo settimanale e corsi) sono sospese fino a Pasqua. Si riprenderà la settimana successiva: giovedì 13 torneo interno, sabato 15 corso bambini e ragazzi.</div>','sospensione-attivita-fino-a-pasqua-2399','2023-04-03 00:00:00',NULL),(2400,1,'Inizio corsi di scacchi 2023','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Iniziano i corsi di scacchi presso la sala della circoscrizione comunale CTP 5, in largo Petrarca n. 3. La prima lezione di ciascun corso si terrà come segue:\n- corso di secondo livello: giovedì 16 febbraio, ore 21:30-23:00\n- corso di primo livello: sabato 18 febbraio, ore 16:30-18:00\n- corso bambini/ragazzi (1º gruppo): sabato 18 febbraio, ore\n15:00-16:30\n- corso bambini/ragazzi (2º gruppo): sabato 18 febbraio, ore\n16:30-18:00</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">I corsi proseguiranno con cadenza settimanale, mantenendo lo stesso giorno e lo stesso orario.</div>','inizio-corsi-di-scacchi-2023-2400','2023-02-15 00:00:00',NULL),(2401,1,'Nuovo ritrovo settimanale','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">A partire da giovedì 16 febbraio, si terrà il nuovo ritrovo settimanale del circolo, ogni giovedì sera dalle 21:30 alle 23:00 presso i locali della circoscrizione comunale CTP 5, in largo Petrarca n. 3.</div>','nuovo-ritrovo-settimanale-2401','2023-02-15 00:00:00',NULL),(2402,1,'Campionato Provinciale di Pisa 2023','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Si è svolto a Pisa i giorni 3, 4, 5 febbraio 2023, presso la Sala Convegni della Stazione Leopolda, il <b>Campionato Provinciale di Pisa</b>, valido come ottavi di finale del Campionato Italiano Assoluto. Fra i 22 partecipanti vince il CM <b>Giulio Simeone</b> con 4 punti su 5. Secondo classificato il CM <b>Antonio Pinto</b> (4 su 5), terzo classificato e campione provinciale il 1N <b>Stefano Taglione</b> (3,5 su 5).</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Fra i 12 partecipanti che si sono dati battaglia nel torneo U1600, vince <b>Antonio Leone</b> con 4,5 punti su 5.</div><div class=\"collegamentograndecentrato\">Risultati e classifiche (<a href=\"https://www.vegaresult.com/it/event.php?id=1049\">Vega Results</a>) (<a href=\"https://vesus.org/festivals/campionato-provinciale-di-pisa-2023-e-torneo-under-1600/\">Vesus</a>)</div>','campionato-provinciale-di-pisa-2023-2402','2023-02-06 00:00:00',NULL),(2403,1,'Partono i corsi di scacchi 2022 per adulti e ragazzi!','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Nella seconda metà di gennaio inizieranno i nuovi corsi di scacchi per adulti e ragazzi fra i 9 e i 18 anni. Per gli adulti sono previsti un corso di livello base e uno avanzato.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Maggiori dettagli nella locandina.</div><div class=\"collegamentograndecentrato\"><a href=\"/file/locandina_corsi_scacchi_2022.png\"><img src=\"file/locandina_corsi_scacchi_2022.png\" width=\"50%\" border=\"2\"></a></div>','partono-i-corsi-di-scacchi-2022-per-adulti-e-ragazzi-2403','2021-12-31 00:00:00',NULL),(2404,1,'Tesseramento FSI 2022','<div class=\"newstext\">Parte il <a href=\"tesseramento2022.php\">tesseramento FSI</a> per il 2022 per disputare tornei e campionati.</div>','tesseramento-fsi-2022-2404','2021-12-01 00:00:00',NULL),(2405,1,'Ritrovo settimanale all\'Albatross, ogni lunedí dalle 21:30','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Riprendono gli incontri settimanali del circolo dal vivo. Si terranno ogni lunedí sera, a partire dalle 21:30, presso il Café Albatross, in via Cavalca, 64. L\'accesso alla sala interna è consentito con la Certificazione verde COVID-19 (cosiddetto \"green pass\"). Si inizia domani 8 novembre.</div>','ritrovo-settimanale-allalbatross-ogni-lunedi-dalle-2130-2405','2021-11-07 00:00:00',NULL),(2406,1,'Corso di scacchi (lezioni rinviate)','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">La <a href=\"http://www.sds.zonapisana.it/index.php?option=com_content&amp;view=article&amp;id=1437%3Acoronavirus-coivid-19-gli-interventi-precauzionali-e-preventivi-della-societa-della-salute-della-zona-pisana&amp;catid=87&amp;Itemid=119&amp;fbclid=IwAR3Vzo5MHzs3j87zwkC-1eepDJCtEVppd9WTcgUZEzJA3frXVrc6T7DRPdk\">Società della Salute Zona Pisana ha disposto la <b>chiusura fino al 14 marzo</b></a> dello SpazioBono 19 e sospeso tutte le relative attività come intervento precauzionale volto a prevenire la diffusione del Coronavirus – Covid 19.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Il corso di scacchi è pertanto sospeso fino a nuova comunicazione.</div>','corso-di-scacchi-lezioni-rinviate-2406','2020-03-03 00:00:00',NULL),(2407,1,'Corso di scacchi (cambio orario)','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Diversamente da quanto precedentemente annunciato, la quarta e la quinta lezione del corso gratuito di scacchi per principianti, organizzato in collaborazione con <a href=\"https://www.facebook.com/spaziobono19/\">Spaziobono19</a>, si terranno martedì 3 marzo e mercoledì 4 marzo in <b>orario unico 18:45–20:30</b>. Non ci saranno pertanto due turni.</div>','corso-di-scacchi-cambio-orario-2407','2020-02-28 00:00:00',NULL),(2408,1,'Campionato provinciale di Pisa 2020','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Si è svolto a Pisa i giorni 14, 15, 16 febbraio 2020, presso la Stazione Leopolda, il <b>Campionato provinciale di Pisa</b>, valido come ottavi di finale del Campionato Italiano Assoluto. Vince il torneo e conquista il titolo di campione provinciale <b>Adriano Cappagli</b>, con 4 punti su 5. Secondo classificato <b>Lucio Calcagnile</b>, anch\'egli con 4/5. Terzo classificato <b>Ezio Alberto Giorgi</b>, con 3,5/5. Si classificano per il campionato regionale Cappagli, Lari e Lufta.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Nel torneo under 1600 vince <b>Mario Nicolini</b> con 4,5 punti su 5.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/campionato-provinciale-di-pisa-campionato-provinciale-di-pisa-2020-e-torneo-under-1600/standing/\" target=\"_blank\">Risultati e classifiche</a></div>','campionato-provinciale-di-pisa-2020-2408','2020-02-17 00:00:00',NULL),(2409,1,'Corso di scacchi (aggiornamento)','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Continuano le lezioni del corso gratuito di scacchi per principianti organizzato dal nostro circolo in collaborazione con <a href=\"https://www.facebook.com/spaziobono19/\">Spaziobono19</a>. I partecipanti sono divisi in due gruppi: il primo dalle 18:15 alle 19:15, il secondo dalle 19:30 alle 20:30 (attenzione: gli orari nella locandina sono sostituiti da questi). <b>Prossime lezioni</b>: martedì 25 febbraio (lezione bonus), mercoledì 26 febbraio (3ª lezione), martedì 3 marzo (4ª lezione), mercoledì 4 marzo (5ª lezione).</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Le lezioni del secondo corso seguiranno probabilmente lo stesso formato del primo corso (due classi, stessi orari), nei giorni 10, 11, 17, 18, 25 marzo (da confermare).</div>','corso-di-scacchi-aggiornamento-2409','2020-02-21 00:00:00',NULL),(2410,1,'Corso di scacchi gratuito aperto a tutti','<div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Si terranno <b>mercoledì 12 febbraio 2020</b> la presentazione e l\'incontro preliminare di due <b>corsi di scacchi gratuiti aperti a tutti</b>, organizzati in collaborazione con <a href=\"https://www.facebook.com/spaziobono19/\">Spaziobono19</a>, Cooperativa Sociale Arnera e Società della Salute Zona Pisana.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Il primo corso, partendo dalle regole, mirerà a fornire le conoscenze di base e a introdurre gli elementi fondamentali di tattica e strategia nelle varie fasi della partita a scacchi (apertura, mediogioco, finale).</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Il secondo corso approfondirà gli elementi tattici e strategici visti nel primo corso e ne introdurrà di più avanzati.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Si potranno seguire entrambi i corsi oppure uno solo. Numero massimo di 20 partecipanti per ciascun corso. È necessaria la preiscrizione.</div><div class=\"newstext\" style=\"margin-bottom: 1.5em;\">Maggiori dettagli nella locandina.</div><div class=\"collegamentograndecentrato\"><a href=\"/file/locandina_corso_scacchi_2020.png\"><img src=\"file/locandina_corso_scacchi_2020.png\" width=\"50%\" border=\"2\"></a></div>','corso-di-scacchi-gratuito-aperto-a-tutti-2410','2020-02-04 00:00:00',NULL),(2411,1,'Riapertura 2025','<div class=\"newstext\">Dopo la pausa natalizia il circolo riaprirà giovedì 9 gennaio con una serata di gioco libero. Vi aspettiamo in sede sempre all\'ex circoscrizione CTP 5 in Largo Petrarca 3. Passare in sede è sempre il modo migliore per rimanere aggiornati su tutte le iniziative in corso! Buone feste e buon anno a tutti!</div>','riapertura-2025-2411','2024-12-29 00:00:00',NULL),(2412,1,'Tesseramento FSI 2025','<div class=\"newstext\">Parte il <a href=\"tesseramento2025.php\">tesseramento FSI</a> per il 2025 per disputare tornei e campionati.</div>','tesseramento-fsi-2025-2412','2024-12-01 00:00:00',NULL),(2413,1,'Chiusura sede giovedì 28 e venerdì 29','<div class=\"newstext\">Giovedì 28 e venerdì 29 novembre la ex circoscrizione 5 rimarrà chiusa per lavori di ristrutturazione e pertanto il circolo sarà chiuso. Sarà nostra cura informarvi sulla riapertura.</div>','chiusura-sede-giovedi-28-e-venerdi-29-2413','2024-11-28 00:00:00',NULL),(2414,1,'7° torneo weekend “Scacchi Sotto La Torre”','<div class=\"newstext\">\n							Sabato e domenica 2-3 novembre si è svolto, presso il circolo Arci Giacomo Matteotti di Riglione (Pisa), il <b>7° torneo weekend “Scacchi Sotto La Torre”</b>. L’iniziativa è stata un grande successo con ben 95 partecipanti totali nei tre gironi che si sono disputati. \n							Nel <b>torneo C</b>, in cui si sono battuti la bellezza di 53 giocatori con Elo inferiore di 1600, ha avuto la meglio <b>Giuseppe Totino</b> con un en plein di 5 punti su 5, seguito da <b>Dario Zampolini</b> (4.5/5) e <b>Svetlana Perfilyeva</b> (4/5). 4° classificato il nostro <b>Marco Cellucci</b> seguito in quinta posizione da <b>Leonardo Gai</b>.\n							Il <b>torneo B</b>, composto da 26 giocatori con Elo maggiore di 1600 e minore di 1800, ha visto in cima al podio <b>Gabriele Guagliardo</b> (4/5). Al secondo posto <b>Giuseppe Palaia</b> con 4 punti su 5 ma Bucholz inferiore, seguito al terzo posto da <b>Andrea Taccia</b> (3.5/5).\n							Gli spareggi tecnici hanno dovuto determinare il podio del combattutissimo <b>torneo A</b> (Elo &gt; 1800). Il primo posto è andato al IM <b>Virgilio Vuelban</b> (4/5). 2° classificato CM <b>Edoardo Fulgentini</b> (4/5). 3° classificato CM <b>Federico Esposti</b> (4/5). Seguono al 4° e 5° posto FM <b>Doriano Tocchioni</b> e <b>Lorenzo Demeio</b>.\n							Assegnati anche premi di fascia: il miglior giocatore under 1500 è stato il nostro <b>Giorgi Lomtadze</b> che con questo torneo ha conseguito la terza categoria nazionale! Miglior under 1700: <b>Francesco Vocali</b>. Miglior under 1900: <b>Marino Cosci</b>. Infine, il premio per miglior giocatore under 14 è andato ad <b>Aron Pratelli</b> e il premio per miglior under 10 al nostro <b>Samuele Soriani</b>.\n							Grazie a tutti e appuntamento alla prossima edizione!\n							</div><div class=\"collegamentograndecentrato\">\n								<a href=\"foto/2024-11_SSLT/3.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/3.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/4.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/4.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/5.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/5.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/6.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/6.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/7.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/7.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/17.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/17.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/18.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/18.jpg\" width=\"13%\" border=\"1\"></a>\n							</div><div class=\"collegamentograndecentrato\">\n								<a href=\"foto/2024-11_SSLT/8.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/8.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/9.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/9.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/10.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/10.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/11.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/11.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/12.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/12.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/13.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/13.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/15.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/15.jpg\" width=\"13%\" border=\"1\"></a>\n\n							</div><div class=\"collegamentograndecentrato\">\n								<a href=\"foto/2024-11_SSLT/14.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/14.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/1.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/1.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/2.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/2.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"foto/2024-11_SSLT/16.jpg\" target=\"_blank\"><img src=\"foto/2024-11_SSLT/16.jpg\" width=\"13%\" border=\"1\"></a>\n							</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/0FenWGLq\" target=\"_blank\">Risultati e classifiche</a></div>','7-torneo-weekend-scacchi-sotto-la-torre-2414','2024-11-06 00:00:00',NULL),(2415,1,'Torneo sociale rapid','<div class=\"newstext\">Si è svolto venerdì 25 ottobre il primo torneo sociale Rapid del venerdì sera, con un’ottima partecipazione di ben 16 partecipanti. Vince il torneo Stefano Taglione con ben 5 punti su 5 partite. Secondo classificato Marco Cellucci a cui fa seguito sul podio Filippo Velli. Il premio miglior non agonista è andato a  Adriano Cappagli e premio miglior under 18 al giovane Marco Pallini. Grazie a tutti e al prossimo torneo sociale!</div><div class=\"collegamentograndecentrato\">\n								<a href=\"foto/25_10_2024_rapid_sociale/01.jpeg\" target=\"_blank\"><img src=\"foto/25_10_2024_rapid_sociale/01.jpeg\" width=\"30%\" border=\"1\"></a>\n								<a href=\"foto/25_10_2024_rapid_sociale/02.jpeg\" target=\"_blank\"><img src=\"foto/25_10_2024_rapid_sociale/02.jpeg\" width=\"30%\" border=\"1\"></a>\n								<a href=\"foto/25_10_2024_rapid_sociale/03.jpeg\" target=\"_blank\"><img src=\"foto/25_10_2024_rapid_sociale/03.jpeg\" width=\"30%\" border=\"1\"></a>\n							</div><div class=\"collegamentograndecentrato\">\n							<a href=\"foto/25_10_2024_rapid_sociale/04.jpeg\" target=\"_blank\"><img src=\"foto/25_10_2024_rapid_sociale/04.jpeg\" width=\"30%\" border=\"1\"></a>\n							<a href=\"foto/25_10_2024_rapid_sociale/05.jpeg\" target=\"_blank\"><img src=\"foto/25_10_2024_rapid_sociale/05.jpeg\" width=\"30%\" border=\"1\"></a>\n							</div>','torneo-sociale-rapid-2415','2024-10-27 00:00:00',NULL),(2416,1,'Riprendono i corsi di scacchi al circolo','<div class=\"newstext\">A partire da sabato 12 Ottobre, presso il Centro Polivalente San Zeno, si terranno:\n							<ul>\n							<li>Un corso per adulti principianti.\n							</li><li>Un corso per bambini principianti.\n							</li><li>Un corso per bambini di livello intermedio, che sanno già giocare e desiderano affinare la tecnica di gioco.\n							</li></ul>\n							Il numero dei posti sarà limitato per consentire un miglior servizio, pertanto si consiglia di prenotare il prima possibile.\n							Per ulteriori informazioni, orari, costi e prenotazioni scrivere a: info@scacchilatorre.it, oppure contattare il numero di telefono: 3207075700.\n							Buon gioco a tutti!</div><div class=\"collegamentograndecentrato\">\n								<a href=\"corsi/2024-set-dic-bambini.jpg\" target=\"_blank\"><img src=\"corsi/2024-set-dic-bambini.jpg\" width=\"40%\" border=\"1\"></a>\n								<a href=\"corsi/2024-set-dic-adulti.jpg\" target=\"_blank\"><img src=\"corsi/2024-set-dic-adulti.jpg\" width=\"40%\" border=\"1\"></a>\n							</div>','riprendono-i-corsi-di-scacchi-al-circolo-2416','2024-09-25 00:00:00',NULL),(2417,1,'Campionato Regionale a Squadre under 18','<div class=\"newstext\">Si è svolto domenica 15 settembre a Castiglione della Pescaia il Campionato Regionale a squadre under 18 a cui abbiamo partecipato con due squadre, una under 18 e una under 14. La squadra under 18, composta da Leandro Trincherini, Gioele Pennoni, Taddeo Moriconi e Dario Mariani, ha totalizzato 1 vittoria, 3 patte e 2 sconfitte, ma con prestazioni molto solide e combattute. La squadra under 14, composta da Marco Cellucci, Giorgi Lomtadze, Samuele Soriani e Giulio Piarulli, ha fatto un torneo emozionante, totalizzando una vittoria, 2 pareggi e 3 sconfitte. Un grande ringraziamento va ai nostri due under 10, Giorgi e Samuele, e al nostro under 12 Giulio, che molto coraggiosamente si sono messi in gioco nel torneo dei più grandi! Bravi! Grazie ragazzi, e alla prossima sfida!</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/2vrlMgpJ\" target=\"_blank\">Risultati e classifiche</a></div><div class=\"collegamentograndecentrato\">\n								<a href=\"foto/2024-09_CISU18/01.jpeg\" target=\"_blank\"><img src=\"foto/2024-09_CISU18/01.jpeg\" width=\"30%\" border=\"1\"></a>\n								<a href=\"foto/2024-09_CISU18/02.jpeg\" target=\"_blank\"><img src=\"foto/2024-09_CISU18/02.jpeg\" width=\"30%\" border=\"1\"></a>\n								<a href=\"foto/2024-09_CISU18/03.jpeg\" target=\"_blank\"><img src=\"foto/2024-09_CISU18/03.jpeg\" width=\"30%\" border=\"1\"></a>\n							</div><div class=\"collegamentograndecentrato\">\n								<a href=\"foto/2024-09_CISU18/05.jpeg\" target=\"_blank\"><img src=\"foto/2024-09_CISU18/05.jpeg\" width=\"30%\" border=\"1\"></a>\n								<a href=\"foto/2024-09_CISU18/06.jpeg\" target=\"_blank\"><img src=\"foto/2024-09_CISU18/06.jpeg\" width=\"30%\" border=\"1\"></a>\n								<a href=\"foto/2024-09_CISU18/10.jpeg\" target=\"_blank\"><img src=\"foto/2024-09_CISU18/10.jpeg\" width=\"30%\" border=\"1\"></a>\n							</div>','campionato-regionale-a-squadre-under-18-2417','2024-09-17 00:00:00',NULL),(2418,1,'Riprendono i giovedì al circolo','<div class=\"newstext\">Da giovedì 12 settembre riprende il ritrovo settimanale del circolo alle 21:30, sempre nei locali dell\'ex circoscrizione CTP 5 in Largo Petrarca 3. Vi aspettiamo!</div>','riprendono-i-giovedi-al-circolo-2418','2024-09-10 00:00:00',NULL),(2419,1,'Posticipazione incontro settimanale','<div class=\"newstext\">Per cause di forza maggiore indipendenti dalla volontà del circolo, la ripresa dell\'incontro settimanale del giovedì, prevista per il 5 settembre, è rimandata a data da destinarsi. Comunicheremo al più presto luogo e data del nuovo incontro settimanale del circolo.</div>','posticipazione-incontro-settimanale-2419','2024-09-04 00:00:00',NULL),(2420,1,'VII Torneo \"Scacchi Sotto la Torre\"','<div class=\"newstext\">Sabato 2 e domenica 3 novembre si svolgerà a Pisa presso la sala del Circolo ARCI La Pagoda in via Fiorentina 545 il <b>VII Torneo “Scacchi Sotto La Torre”</b>. Il torneo, omologato FSI/FIDE e valido per variazioni Elo FIDE standard, prevederà 5 turni a partire dalle 14:00 di sabato, con 60 minuti per giocatore e 30 secondi per mossa come cadenza di gioco. Sono previsti tre tornei suddivisi per fasce Elo. Torneo A: Elo &gt; 1800, torneo B: Elo  1600, torneo C: Elo \n                            </div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/0FenWGLq\" target=\"_blank\">Preiscrizioni e bando</a></div><div class=\"collegamentograndecentrato\">\n								<img src=\"/pics/7SLT.jpg\" width=\"100%\" border=\"1\">\n							</div>','vii-torneo-scacchi-sotto-la-torre-2420','2024-09-03 00:00:00',NULL),(2421,1,'Ripresa attività di circolo 5 settembre','<div class=\"newstext\">Di ritorno dalla pausa estiva il Circolo Scacchistico \"La Torre\" si ritrova come di consueto ogni giovedì alle 21:30 presso i locali del CPT 5 in largo Petrarca. Vi aspettiamo giovedì!</div>','ripresa-attivita-di-circolo-5-settembre-2421','2024-09-02 00:00:00',NULL),(2422,1,'CHIUSURA ESTIVA','<div class=\"newstext\">Il Circolo Scacchistico “La Torre” chiude per ferie. Le attività riprenderanno a settembre. Buone vacanze a tutti!</div><div class=\"collegamentograndecentrato\">\n								<img src=\"/pics/chiusura.jpg\" width=\"60%\" border=\"1\">\n							</div>','chiusura-estiva-2422','2024-07-26 00:00:00',NULL),(2423,1,'CONVOCAZIONE ASSEMBLEA ELETTIVA','<div class=\"newstext\">È convocata per il giorno giovedí 18 luglio 2024, in prima convocazione alle ore 01:00 ed occorrendo in seconda convocazione alle ore 21:45, presso i locali della Circoscrizione 5 in largo Petrarca, l\'assemblea dei soci dell\'A.S.D. Circolo Scacchistico “La Torre” col seguente ordine del giorno:\n							<ol>\n                            <li>elezione organi statutari (Presidente e Consiglio Direttivo);\n							</li><li>discussione sulle attività svolte e proposte per le attività della stagione 2024-2025;\n							</li><li>discussione e proposte per la formazione di gruppi di lavoro;\n							</li><li>varie ed eventuali.\n                            </li></ol>\n                            </div>','convocazione-assemblea-elettiva-2423','2024-07-03 00:00:00',NULL),(2424,1,'CONVOCAZIONE ASSEMBLEA STRAORDINARIA','<div class=\"newstext\">È convocata, presso i locali della Circoscrizione 5 in largo Petrarca a Pisa, l\'assemblea straordinaria dei soci dell\'A.D. Circolo Scacchistico “La Torre” per il giorno giovedì 27 giugno 2024, alle ore 03:30 in prima convocazione ed occorrendo in seconda convocazione per lo stesso giorno alle ore 21:45, per discutere e deliberare sul seguente ordine del giorno:\n                            <ol>\n                            <li>adeguamento dello statuto;\n                            </li><li>varie ed eventuali.\n                            </li></ol>\n                            </div>','convocazione-assemblea-straordinaria-2424','2024-06-12 00:00:00',NULL),(2425,1,'GREAT! Pisa in gioco','<div class=\"newstext\">Saremo presenti <b>sabato 18 maggio dalle 10 alle 18</b> alla manifestazione <b>GREAT! Pisa in gioco</b> sotto le Logge di Banchi. Gioco libero e lezione bambini dalle 15 alle 16. Passate a trovarci!</div><div class=\"collegamentograndecentrato\">\n								<a href=\"/eventi/2024-05-18_GREAT_Pisa-in-gioco.jpeg\" target=\"_blank\"><img src=\"/eventi/2024-05-18_GREAT_Pisa-in-gioco.jpeg\" width=\"100%\" border=\"1\"></a>\n							</div>','great-pisa-in-gioco-2425','2024-05-10 00:00:00',NULL),(2426,1,'Primavera Pisana 2024','<div class=\"newstext\">Ottima partecipazione al <b>1º torneo round robin Primavera Pisana</b>, svoltosi a Pisa i giorni 27 e 28 aprile presso la Sala Convegni della Stazione Leopolda. La manifestazione ha visto darsi battaglia ben <b>58 giocatori</b>, provenienti anche da fuori regione, suddivisi per Elo decrescente in 8 tornei round robin da 6 giocatori ciascuno e in un torneo svizzero (10 giocatori) riservato ai giocatori con punteggio Elo minore di 1600.</div><div class=\"newstext\">Torneo A (1929 &amp;leq; Elo &amp;leq; 1983): 1º <b>Maziar Ghods</b> (3,5/5), 2º <b>Riccardo Costalonga</b> (3/5), 3º <b>Lucio Calcagnile</b> (3/5)</div><div class=\"newstext\">Torneo B (1836 &amp;leq; Elo &amp;leq; 1902): 1º <b>Romualdo Vitale</b> (3,5/5)</div><div class=\"newstext\">Torneo C (1724 &amp;leq; Elo &amp;leq; 1803): 1º <b>Francesco Saverio Valgimigli</b> (3,5/5)</div><div class=\"newstext\">Torneo D (1652 &amp;leq; Elo &amp;leq; 1695): 1º <b>Ferruccio Lari</b> (4/5)</div><div class=\"newstext\">Torneo E (1618 &amp;leq; Elo &amp;leq; 1650): 1º <b>Massimo Morganti</b> (3,5/5)</div><div class=\"newstext\">Torneo F (1540 &amp;leq; Elo &amp;leq; 1615): 1º <b>Leandro Trincherini</b> (4,5/5)</div><div class=\"newstext\">Torneo G (1494 &amp;leq; Elo &amp;leq; 1529): 1º <b>Filippo Buonagurio</b> (3,5/5)</div><div class=\"newstext\">Torneo H (1399 &amp;leq; Elo &amp;leq; 1484): 1º <b>Lorenzo Cioli</b> (5/5)</div><div class=\"newstext\">Torneo svizzero (1399 &amp;leq; Elo &amp;leq; 1515): 1º <b>Marcello Tamburini</b> (4,5/5)</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/neJcpTJf\" target=\"_blank\">Risultati e classifiche</a></div>','primavera-pisana-2024-2426','2024-04-29 00:00:00',NULL),(2427,1,'Campionato Italiano a Squadre','<div class=\"newstext\">Il nostro circolo chiude il CIS – serie Promozione con un 2º posto per la prima squadra e un 5º posto per la seconda. Hanno giocato Lucio Calcagnile, Marco Montesanti, Michele Casarosa, Martino Salbego, Leandro Trincherini, Lorenzo Di Puccio, Matteo Toso, Antonio Cerina, Francesco Piqué, Michele Parducci, Marco Cellucci e Vincenzo Silluzio. Grazie a tutti quanti! Con volti vecchi e nuovi siamo ritornati a giocare un CIS dopo cinque anni dall\'ultima partecipazione ed è stata una bella esperienza. L\'anno prossimo ci saremo di nuovo!</div><div class=\"collegamentograndecentrato\">\n								<a href=\"/foto/2024-03_CIS/2024-03_CIS_Toscana4.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/2024-03_CIS_Toscana4.jpg\" width=\"25%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/2024-03_CIS_Toscana1.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/2024-03_CIS_Toscana1.jpg\" width=\"25%\" border=\"1\"></a>\n							</div><div class=\"collegamentograndecentrato\">\n								<a href=\"/foto/2024-03_CIS/01.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/01.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/02.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/02.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/03.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/03.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/04.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/04.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/05.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/05.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/06.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/06.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/07.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/07.jpg\" width=\"13%\" border=\"1\"></a>\n							</div><div class=\"collegamentograndecentrato\">\n								<a href=\"/foto/2024-03_CIS/08.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/08.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/09.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/09.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/10.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/10.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/11.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/11.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/12.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/12.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/13.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/13.jpg\" width=\"13%\" border=\"1\"></a>\n								<a href=\"/foto/2024-03_CIS/14.jpg\" target=\"_blank\"><img src=\"/foto/2024-03_CIS/14.jpg\" width=\"13%\" border=\"1\"></a>\n							</div>','campionato-italiano-a-squadre-2427','2024-03-17 00:00:00',NULL),(2428,1,'Campionato Provinciale giovanile di Pisa 2024','<div class=\"newstext\"><p>Si è svolto a Pisa il giorno 10 marzo 2024, presso la Stazione Leopolda, il <b>Campionato Provinciale Giovanile di Pisa</b>, valido come qualificazione alla finale del Campionato Italiano Giovanile. Hanno partecipato 35 ragazzi, perlopiù del nostro circolo, ma alcuni provenienti da altri circoli della Toscana e della Liguria. Una bella festa degli scacchi per grandi e piccoli e un risultato importante per la nostra associazione, che da due anni ha ricominciato a investire sui più giovani. Al termine del torneo sono stati distribuiti a tutti delle medaglie ricordo e dei simpatici cioccolatini a tema scacchistico, questi ultimi realizzati da <a href=\"https://www.cioccolatoargento.it/\" target=\"_blank\"> Cioccolato Argento.</a></p>\n                            <h4>Campioni provinciali</h4>\n                            <ul>\n                            <li><strong> Under 8 assoluto:</strong> Filippo Corbetta\n                            </li><li><strong> Under 8 femminile:</strong> Linda Layla Bagnoli\n                            </li><li><strong> Under 10 assoluto:</strong> Giorgi Lomtadze\n                            </li><li><strong> Under 10 femminile:</strong> Sveva Bagnoli\n                            </li><li><strong> Under 12 assoluto:</strong> Sofiia Kutishcheva\n                            </li><li><strong> Under 12 femminile:</strong> Ilaria Del Guerra\n                            </li><li><strong> Under 14 assoluto:</strong> Marco Cellucci\n                            </li><li><strong> Under 18 assoluto:</strong> Michele Parducci\n                            </li></ul>\n                            </div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/qlJHxc57\" target=\"_blank\">Risultati e classifiche</a></div>','campionato-provinciale-giovanile-di-pisa-2024-2428','2024-03-13 00:00:00',NULL),(2429,1,'CONVOCAZIONE ASSEMBLEA ORDINARIA','<div class=\"newstext\">È convocata in Pisa, presso i locali della Circoscrizione 5 in largo Petrarca, l\'assemblea ordinaria dei soci dell\'A.D. Circolo Scacchistico “La Torre”, per il giorno giovedì 21 marzo 2024, alle ore 04:00 in prima convocazione ed occorrendo in seconda convocazione per lo stesso giorno alle ore 22:30, per discutere e deliberare sul seguente ordine del giorno:\n                            <ol>\n                            <li>Approvazione del rendiconto economico-finanziario 2023;\n                            </li><li>Approvazione del programma di attività per il 2024;\n                            </li><li>Varie ed eventuali.\n                            </li></ol>\n                            </div>','convocazione-assemblea-ordinaria-2429','2024-03-03 00:00:00',NULL),(2430,1,'CONVOCAZIONE ASSEMBLEA STRAORDINARIA','<div class=\"newstext\">È convocata in Pisa, presso i locali della Circoscrizione 5 in largo Petrarca, l\'assemblea straordinaria dei soci dell\'A.D. Circolo Scacchistico “La Torre”, per il giorno giovedì 21 marzo 2024, alle ore 03:30 in prima convocazione ed occorrendo in seconda convocazione per lo stesso giorno alle ore 22:00, per discutere e deliberare sul seguente ordine del giorno:\n                            <ol>\n                            <li>Cambio sede legale dell\'Associazione;\n                            </li><li>Adeguamento dello statuto;\n                            </li><li>Varie ed eventuali.\n                            </li></ol>\n                            </div>','convocazione-assemblea-straordinaria-2430','2024-03-03 00:00:00',NULL),(2431,1,'Scuola di scacchi under 14','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Riprende la scuola di scacchi coi nuovi corsi per bambini e ragazzi dai 6 ai 14 anni. Primo appuntamento il 2 marzo. Tutti i dettagli nella locandina, ulteriori informazioni per telefono o email.</div><div class=\"collegamentograndecentrato\"><a href=\"/corsi/2024-mar-mag_scuola-scacchi-bambini-e-ragazzi.jpg\" target=\"_blank\"><img src=\"/corsi/2024-mar-mag_scuola-scacchi-bambini-e-ragazzi.jpg\" width=\"60%\" border=\"2\"></a></div>','scuola-di-scacchi-under-14-2431','2024-02-29 00:00:00',NULL),(2432,1,'Campionato Provinciale di Pisa 2024','<div class=\"newstext\">Si è svolto a Pisa i giorni 9, 10, 11 febbraio 2024, presso la Stazione Leopolda, il <b>Campionato Provinciale di Pisa</b>, valido come ottavi di finale del Campionato Italiano Assoluto. Il Campionato Provinciale ha visto la partecipazione di 27 giocatori ed è stato vinto da Luca Mazzanti, davanti a Sara Celati e Michele Casarosa, che si laurea campione provinciale. Al torneo Under 1600 hanno partecipato 15 giocatori; la vittoria è andata a Francesco Piqué, che ha preceduto Antonio Cerina e Marco Cellucci.</div><div class=\"collegamentograndecentrato\"><a href=\"https://vesus.org/event/qyg-_yoT\" target=\"_blank\">Risultati e classifiche</a></div>','campionato-provinciale-di-pisa-2024-2432','2024-02-16 00:00:00',NULL),(2433,1,'Ripartenza scuola di scacchi per bambini','<div class=\"newstext\" style=\"margin-bottom: 0.4em;\">Riparte dopo la pausa per le feste la scuola di scacchi per bambini dai 6 ai 10 anni. Primo appuntamento il 13 gennaio. Tutti i dettagli nella locandina, ulteriori informazioni per email.</div><div class=\"collegamentograndecentrato\"><a href=\"/corsi/2024-gen-feb_scuola-scacchi-bambini.jpg\"><img src=\"/corsi/2024-gen-feb_scuola-scacchi-bambini.jpg\" width=\"60%\" border=\"2\"></a></div>','ripartenza-scuola-di-scacchi-per-bambini-2433','2024-01-02 00:00:00',NULL),(2434,1,'4º torneo weekend “Scacchi sotto la Torre”','<div class=\"newstext\">Si è svolto a Pisa nei giorni 26, 27, 28 ottobre, presso i locali della Stazione Leopolda, il <b>4º torneo weekend “Scacchi sotto la Torre”</b>. Presenti 8 partecipanti nel torneo A (Elo ≥ 1750) e 16 nel torneo B (Elo &lt; 1800). Vince il torneo A <b>Luciano Rosato</b> con 3,5 punti su 5, seguito a pari punti da <b>Ugo Bindini</b> (2º) e <b>Fabio Bartoli</b> (3º). Il premio di fascia per Elo &lt; 1900 è andato a <b>Michele Casarosa</b>. Vince il torneo B <b>Rrapush Lufta</b> con 4,5 punti su 5, seguito da <b>Sara Celati</b> (4/5) e <b>Francesco Fornai</b> (4/5). Il premio di fascia per Elo &lt; 1600 è andato a <b>Federico Topaios</b>.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/festivals/4ordm-torneo-weekend-scacchi-sotto-la-torre/\" target=\"_blank\">Risultati e classifiche</a></div>','4-torneo-weekend-scacchi-sotto-la-torre-2434','2018-10-28 00:00:00',NULL),(2435,1,'11º Semilampo di Pisa','<div class=\"newstext\">Dopo due anni di pausa è tornato il torneo Semilampo di Pisa! L\'11ª edizione del nostro torneo valido per l\'Elo rapid FIDE si è svolta domenica 20 maggio presso le <a href=\"http://officinegaribaldi.it/\" target=\"_blank\">Officine Garibaldi</a>, in via Gioberti 39 a Pisa. Il torneo (7 turni, tempo Fischer 12\' + 5\") ha visto la vittoria di Sergejs Gromovs a punteggio pieno. Completano il podio Lucio Calcagnile (5,5/7) e Daniele Bettazzi (4,5/7).</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/tournaments/11ordm-torneo-semilampo-di-pisa/\" target=\"_blank\">Risultati e classifica finale</a></div>','11-semilampo-di-pisa-2435','2018-05-20 00:00:00',NULL),(2436,1,'Campionato interprovinciale di Pisa e Livorno 2018','<div class=\"newstext\">Si è svolto a Pisa i giorni 2, 3, 4 febbraio 2018, presso la Stazione Leopolda, il <b>Campionato interprovinciale di Pisa e Livorno</b>, valido come ottavi di finale del Campionato Italiano Assoluto per le due province. Vince il torneo <b>Federico Esposti</b>, con 4,5 punti su 5 partite, precedendo per spareggio tecnico <b>Giulio Calavalle</b>. Terzo classificato il nostro <b>Lucio Calcagnile</b> (4/5), che conquista anche il titolo di campione provinciale precedendo per spareggio tecnico il nostro <b>Ugo Bindini</b>, protagonista anch\'egli di un ottimo torneo. Campione provinciale di Livorno si laurea nuovamente <b>Massimo Bardi</b>.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/results/campionato-interprovinciale-di-pisa-e-livorno-campionato-interprovinciale-di-pisa-e-livorno-2018-e-torneo-under-1500/\" target=\"_blank\">Risultati e classifiche</a></div>','campionato-interprovinciale-di-pisa-e-livorno-2018-2436','2018-02-05 00:00:00',NULL),(2437,1,'Campionato interprovinciale di Pisa e Livorno 2019','<div class=\"newstext\">Si è svolto a Pisa i giorni 18, 19, 20 gennaio 2019, presso la Stazione Leopolda, il <b>Campionato interprovinciale di Pisa e Livorno</b>, valido come ottavi di finale del Campionato Italiano Assoluto per le due province. Fra venti partecipanti, vince il torneo <b>Ermanno Pacini</b> con 4,5 punti su 5 partite, secondo classificato e campione provinciale di Livorno <b>Massimo Bardi</b> (3,5/5), terzo classificato e campione provinciale di Pisa <b>Lucio Calcagnile</b> (3,5/5). Al campionato interprovinciale si è affiancato un torneo riservato a giocatori con punteggio Elo inferiore a 1600, vinto da <b>Raul Barbetti</b> (3,5 punti su 5), che la spunta sui nove partecipanti.</div><div class=\"collegamentograndecentrato\"><a href=\"http://vesus.org/festivals/campionato-interprovinciale-di-pisa-e-livorno-2019-e-torneo-under-1600/\" target=\"_blank\">Risultati e classifiche</a></div>','campionato-interprovinciale-di-pisa-e-livorno-2019-2437','2019-01-22 00:00:00',NULL);
